window.__qzParts=window.__qzParts||{};window.__qzParts.congnghe=[{"p":"Vai trò quan trọng nhất của nhà ở đối với mỗi gia đình là gì?","o":["Là nơi ở, sinh hoạt và sum họp của các thành viên trong gia đình","Là nơi để xe và chứa đồ cũ","Là nơi chỉ để tiếp khách","Là nơi kinh doanh, buôn bán"],"a":"Là nơi ở, sinh hoạt và sum họp của các thành viên trong gia đình","h":"Hãy nghĩ đến nơi các thành viên trong gia đình sống cùng nhau mỗi ngày.","e":"Nhà ở là nơi các thành viên trong gia đình cùng sinh sống, sinh hoạt, nghỉ ngơi và sum họp sau mỗi ngày.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật liệu nào thường được dùng để xây tường nhà?","o":["Vải bạt","Gạch","Giấy các-tông","Lá cây khô"],"a":"Gạch","h":"Đây là vật liệu nung từ đất sét, rất phổ biến ở các công trình nhà ở.","e":"Gạch (gạch nung hoặc gạch không nung) kết hợp với vữa xi măng là vật liệu phổ biến nhất để xây tường nhà ở nước ta.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khu vực nào trong nhà thường dùng để nấu ăn?","o":["Phòng ngủ","Phòng khách","Khu vực bếp","Phòng vệ sinh"],"a":"Khu vực bếp","h":"Đây là nơi đặt bếp nấu và chuẩn bị thức ăn.","e":"Khu vực bếp là nơi nấu nướng và chuẩn bị thức ăn cho gia đình, thường bố trí gần khu vực ăn uống.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhà ở thông minh có đặc điểm nổi bật nào?","o":["Được sơn rất nhiều màu sắc","Có thật nhiều cửa sổ lớn","Được xây bằng vật liệu đắt tiền nhất","Các thiết bị trong nhà có thể điều khiển tự động hoặc từ xa, tiện nghi và tiết kiệm năng lượng"],"a":"Các thiết bị trong nhà có thể điều khiển tự động hoặc từ xa, tiện nghi và tiết kiệm năng lượng","h":"Hãy nghĩ đến việc bật tắt đèn, điều hòa bằng điện thoại từ xa.","e":"Nhà ở thông minh ứng dụng công nghệ để điều khiển đèn, điều hòa, rèm cửa... tự động hoặc từ xa, giúp cuộc sống tiện nghi và tiết kiệm năng lượng.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Một ngôi nhà ở tốt cần đáp ứng yêu cầu cơ bản nào?","o":["Chắc chắn, an toàn và thuận tiện cho sinh hoạt của gia đình","Càng cao nhiều tầng càng tốt","Chỉ cần đẹp là đủ","Càng rộng thì càng tốt, không cần chắc chắn"],"a":"Chắc chắn, an toàn và thuận tiện cho sinh hoạt của gia đình","h":"Nhà trước hết phải bảo vệ được người ở bên trong.","e":"Nhà ở cần được xây dựng chắc chắn, bền vững, đảm bảo an toàn, đồng thời thuận tiện và thoải mái cho sinh hoạt hằng ngày.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khu vực sinh hoạt chung của gia đình trong nhà thường là khu vực nào?","o":["Phòng vệ sinh","Phòng khách","Nhà kho","Ban công"],"a":"Phòng khách","h":"Đây là nơi gia đình tiếp khách và quây quần xem ti vi.","e":"Phòng khách là khu vực sinh hoạt chung, nơi gia đình tiếp khách, trò chuyện và sum họp.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải sợi thiên nhiên được làm từ nguồn nguyên liệu nào?","o":["Từ dầu mỏ","Từ nhựa tái chế","Từ thực vật và động vật như bông, tơ tằm, len","Từ sợi kim loại"],"a":"Từ thực vật và động vật như bông, tơ tằm, len","h":"Sợi thiên nhiên có sẵn trong tự nhiên, từ cây cỏ hoặc động vật.","e":"Vải sợi thiên nhiên được dệt từ sợi có trong tự nhiên: sợi bông từ cây bông, tơ tằm từ kén tằm, len từ lông cừu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải sợi hoá học thường có đặc điểm nào?","o":["Chỉ may được trang phục một màu","Rất dễ rách và nhanh hỏng","Thấm hút mồ hôi tốt hơn mọi loại vải thiên nhiên","Ít bị nhàu, bền, giá thành thường thấp hơn vải thiên nhiên"],"a":"Ít bị nhàu, bền, giá thành thường thấp hơn vải thiên nhiên","h":"Sợi hoá học do con người tạo ra trong nhà máy.","e":"Vải sợi hoá học do con người tạo ra, thường ít nhàu, bền, màu sắc đa dạng và giá thành thấp, nhưng thoáng mát kém hơn vải thiên nhiên.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi lựa chọn trang phục đi học, em cần chú ý điều gì?","o":["Trang phục phù hợp với lứa tuổi, hoàn cảnh và quy định của nhà trường","Trang phục càng đắt tiền càng tốt","Trang phục phải theo mốt mới nhất","Trang phục phải giống hệt của bạn bè"],"a":"Trang phục phù hợp với lứa tuổi, hoàn cảnh và quy định của nhà trường","h":"Trang phục đi học cần gọn gàng, đúng quy định của trường.","e":"Trang phục đi học cần phù hợp lứa tuổi, gọn gàng, lịch sự và tuân thủ quy định của nhà trường, không nên chạy theo mốt hay giá tiền.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Cách bảo quản trang phục nào là đúng?","o":["Giặt chung tất cả các màu với nhau","Giặt sạch, phơi nơi thoáng, là (ủi) và cất ở nơi khô ráo","Để quần áo còn ẩm trong tủ kín","Vò thật mạnh mọi loại vải khi giặt"],"a":"Giặt sạch, phơi nơi thoáng, là (ủi) và cất ở nơi khô ráo","h":"Quần áo ẩm mốc là do cất giữ nơi ẩm ướt.","e":"Trang phục cần giặt sạch, phơi ở nơi thoáng mát, là (ủi) cho phẳng và cất giữ ở nơi khô ráo để tránh ẩm mốc, hư hỏng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trước khi là (ủi) quần áo, em cần lưu ý điều gì?","o":["Luôn để bàn là ở mức nhiệt cao nhất","Không cần kiểm tra gì, cứ là thật nhanh","Xem hướng dẫn trên nhãn quần áo và chọn nhiệt độ phù hợp với từng loại vải","Chỉ là quần áo khi còn ướt sũng"],"a":"Xem hướng dẫn trên nhãn quần áo và chọn nhiệt độ phù hợp với từng loại vải","h":"Mỗi loại vải chịu được một mức nhiệt khác nhau.","e":"Mỗi loại vải chịu nhiệt khác nhau. Xem nhãn hướng dẫn và chỉnh nhiệt độ bàn là phù hợp giúp không làm cháy, hỏng quần áo.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải bông (cotton) được dệt từ sợi bông nên thuộc loại vải nào?","o":["Vải sợi hoá học","Vải sợi tổng hợp","Vải sợi pha","Vải sợi thiên nhiên"],"a":"Vải sợi thiên nhiên","h":"Sợi bông lấy từ quả bông, một loại cây trồng.","e":"Sợi bông được lấy từ cây bông trong tự nhiên nên vải bông thuộc nhóm vải sợi thiên nhiên, có ưu điểm mềm, thấm hút mồ hôi tốt.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Chất đạm có nhiều trong nhóm thực phẩm nào?","o":["Thịt, cá, trứng, sữa và các loại đậu","Cơm, bánh mì, khoai","Rau xanh và trái cây","Dầu ăn và mỡ động vật"],"a":"Thịt, cá, trứng, sữa và các loại đậu","h":"Chất đạm giúp cơ thể lớn lên và khỏe mạnh.","e":"Chất đạm (protein) có nhiều trong thịt, cá, trứng, sữa và các loại đậu, giúp xây dựng và phát triển cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhóm chất bột, đường (như cơm, bánh mì, khoai) chủ yếu cung cấp cho cơ thể điều gì?","o":["Chất xơ","Năng lượng cho cơ thể hoạt động","Vitamin C","Canxi"],"a":"Năng lượng cho cơ thể hoạt động","h":"Đây là \"nhiên liệu\" chính giúp cơ thể hoạt động cả ngày.","e":"Chất bột, đường trong cơm, bánh mì, khoai, ngô là nguồn cung cấp năng lượng chính cho mọi hoạt động của cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Cách bảo quản thực phẩm trong tủ lạnh nào là đúng?","o":["Để thịt sống chung với rau ăn sống","Để thực phẩm ngoài trời nắng cho khô","Đậy kín thực phẩm, để thực phẩm sống và chín ở các ngăn riêng","Không cần đậy nắp hộp đựng thực phẩm"],"a":"Đậy kín thực phẩm, để thực phẩm sống và chín ở các ngăn riêng","h":"Thực phẩm sống có thể làm lây bẩn sang thực phẩm chín.","e":"Thực phẩm trong tủ lạnh cần được đậy kín và để thực phẩm sống, chín ở các ngăn riêng để tránh nhiễm bẩn chéo và giữ được lâu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Để chế biến món ăn đảm bảo an toàn vệ sinh, em cần làm gì?","o":["Không cần rửa tay trước khi nấu ăn","Dùng chung một thớt cho cả thịt sống và thức ăn chín","Nếm thử thịt sống để kiểm tra gia vị","Rửa tay sạch trước khi chế biến và nấu chín kĩ thức ăn"],"a":"Rửa tay sạch trước khi chế biến và nấu chín kĩ thức ăn","h":"Vệ sinh phải được thực hiện từ khâu chuẩn bị đến khi nấu xong.","e":"Rửa tay sạch trước khi chế biến, dùng dụng cụ sạch và nấu chín kĩ thức ăn giúp phòng tránh ngộ độc thực phẩm.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Vitamin và chất khoáng có nhiều trong nhóm thực phẩm nào?","o":["Rau củ và trái cây tươi","Bánh kẹo ngọt","Nước ngọt có ga","Mỡ động vật"],"a":"Rau củ và trái cây tươi","h":"Nhóm này có màu sắc tươi sáng và thường ăn tươi hoặc nấu nhanh.","e":"Rau củ và trái cây tươi chứa nhiều vitamin và chất khoáng, cần thiết cho sức khỏe và sức đề kháng của cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Thực phẩm để lâu, có mùi lạ và đổi màu thì em nên xử lí thế nào?","o":["Vẫn ăn bình thường cho khỏi lãng phí","Không nên sử dụng vì thực phẩm có thể đã bị hỏng, ăn vào không an toàn","Cho thật nhiều gia vị vào rồi ăn","Đem ra phơi nắng rồi ăn tiếp"],"a":"Không nên sử dụng vì thực phẩm có thể đã bị hỏng, ăn vào không an toàn","h":"Mùi lạ và đổi màu là dấu hiệu thực phẩm đã bị hỏng.","e":"Thực phẩm có mùi lạ, đổi màu là đã bị hỏng, có thể chứa vi khuẩn gây ngộ độc nên tuyệt đối không sử dụng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nồi cơm điện gồm các bộ phận chính nào?","o":["Chỉ gồm dây điện và phích cắm","Gồm quạt gió và bóng đèn","Gồm thân nồi, nồi nấu bên trong và bộ phận sinh nhiệt","Gồm bình chứa nước và ống dẫn"],"a":"Gồm thân nồi, nồi nấu bên trong và bộ phận sinh nhiệt","h":"Nồi cơm điện cần có phần chứa gạo và phần tạo ra nhiệt.","e":"Nồi cơm điện gồm thân nồi, nồi nấu (ruột nồi) bên trong và bộ phận sinh nhiệt (mâm nhiệt) giúp nấu chín cơm.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi sử dụng bếp điện, em cần chú ý điều gì để đảm bảo an toàn?","o":["Đặt bếp sát rèm cửa cho tiện nấu","Dùng tay ướt để cắm phích điện","Để khăn ướt phủ lên bếp khi đang nấu","Không để vật dễ cháy gần bếp và không dùng tay ướt chạm vào thiết bị điện"],"a":"Không để vật dễ cháy gần bếp và không dùng tay ướt chạm vào thiết bị điện","h":"Điện và nước, lửa là những yếu tố cần hết sức cẩn thận.","e":"Khi dùng bếp điện phải để xa vật dễ cháy, không dùng tay ướt chạm vào thiết bị và luôn chú ý khi nấu để phòng cháy nổ, điện giật.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Công dụng chính của nồi cơm điện là gì?","o":["Nấu cơm và giữ ấm cơm","Đun nước sôi để pha trà","Xay sinh tố hoa quả","Là (ủi) quần áo"],"a":"Nấu cơm và giữ ấm cơm","h":"Tên của đồ dùng đã nói lên công dụng chính của nó.","e":"Nồi cơm điện dùng để nấu cơm chín đều và có chế độ giữ ấm, giúp cơm luôn nóng khi đến bữa ăn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi nồi cơm điện đang nấu, em không nên làm việc nào?","o":["Đậy kín nắp nồi","Mở nắp liên tục và đưa tay vào vùng hơi nước nóng thoát ra","Đặt nồi trên mặt bàn phẳng, khô ráo","Để nồi xa tầm với của em nhỏ"],"a":"Mở nắp liên tục và đưa tay vào vùng hơi nước nóng thoát ra","h":"Hơi nước nóng thoát ra khi nấu có thể làm bỏng da.","e":"Khi nồi đang nấu, hơi nước nóng thoát ra mạnh. Mở nắp liên tục vừa làm cơm lâu chín, vừa dễ bị bỏng do hơi nóng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao đèn LED được khuyến khích sử dụng trong gia đình thay cho đèn sợi đốt?","o":["Đèn LED sáng chói và toả nhiệt nhiều hơn đèn sợi đốt","Đèn LED rẻ hơn hẳn nhưng nhanh hỏng hơn đèn sợi đốt","Đèn LED tiết kiệm điện hơn và có tuổi thọ cao hơn đèn sợi đốt","Đèn LED không cần cắm điện vẫn sáng được"],"a":"Đèn LED tiết kiệm điện hơn và có tuổi thọ cao hơn đèn sợi đốt","h":"Đèn LED tiêu thụ ít điện năng mà vẫn cho độ sáng tốt.","e":"Đèn LED chuyển hoá phần lớn điện năng thành ánh sáng nên tiết kiệm điện, ít toả nhiệt và bền hơn đèn sợi đốt, giúp gia đình giảm chi phí tiền điện.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi sử dụng bếp hồng ngoại, việc làm nào sau đây là an toàn?","o":["Không chạm tay vào mặt bếp khi đang nấu và một lúc sau khi tắt, vì mặt bếp còn rất nóng","Đặt tay lên mặt bếp để kiểm tra bếp đã nóng chưa","Dùng nồi có đáy cong, lồi lõm để nấu cho nhanh sôi","Lấy khăn ướt lau mặt bếp ngay khi bếp đang nóng đỏ"],"a":"Không chạm tay vào mặt bếp khi đang nấu và một lúc sau khi tắt, vì mặt bếp còn rất nóng","h":"Mặt bếp hồng ngoại nóng đỏ khi nấu và còn nóng rất lâu sau khi tắt.","e":"Khi nấu, mặt bếp hồng ngoại nóng đỏ và truyền nhiệt trực tiếp. Em không được chạm tay vào mặt bếp, nên dùng nồi có đáy phẳng và chờ bếp nguội hẳn rồi mới vệ sinh.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây giúp gia đình em tiết kiệm điện và sử dụng điện an toàn?","o":["Bật đèn sáng cả ngày dù không có người trong phòng","Tắt đèn khi ra khỏi phòng và chọn thiết bị có nhãn năng lượng nhiều sao","Cắm càng nhiều thiết bị vào một ổ cắm càng tốt","Để ti vi ở chế độ chờ suốt ngày đêm"],"a":"Tắt đèn khi ra khỏi phòng và chọn thiết bị có nhãn năng lượng nhiều sao","h":"Nhãn năng lượng trên thiết bị cho biết mức tiết kiệm điện của thiết bị đó.","e":"Tắt đèn khi ra khỏi phòng, tắt thiết bị khi không sử dụng và ưu tiên thiết bị có nhãn năng lượng nhiều sao giúp gia đình tiết kiệm điện, giảm chi phí và an toàn hơn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhà sàn là kiểu nhà ở đặc trưng, thường gặp ở vùng nào sau đây?","o":["Ở các thành phố lớn đông dân cư","Ở miền núi và vùng sông nước hay ngập lụt","Ở vùng sa mạc khô nóng","Ở các khu công nghiệp tập trung"],"a":"Ở miền núi và vùng sông nước hay ngập lụt","h":"Nghĩ xem nhà sàn được dựng cao khỏi mặt đất để tránh điều gì.","e":"Nhà sàn được xây cao trên các cột, giúp tránh ẩm thấp, thú dữ và ngập lụt nên phổ biến ở miền núi và vùng sông nước.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Một ngôi nhà ở thông thường được bố trí gồm những khu vực chức năng chính nào?","o":["Khu vực học tập, khu vực thể thao, khu vực trưng bày và khu vực bán hàng","Khu vực sinh hoạt chung, khu vực nghỉ ngơi, khu vực nấu ăn, ăn uống và khu vực vệ sinh","Khu vực kho chứa, khu vực sản xuất, khu vực văn phòng và khu vực để xe","Khu vực sân vườn, khu vực hồ bơi, khu vực sân thượng và khu vực tầng hầm"],"a":"Khu vực sinh hoạt chung, khu vực nghỉ ngơi, khu vực nấu ăn, ăn uống và khu vực vệ sinh","h":"Kể tên những không gian mà các thành viên trong nhà sử dụng hằng ngày.","e":"Nhà ở được chia thành các khu vực chức năng chính: sinh hoạt chung, nghỉ ngơi, nấu ăn - ăn uống và vệ sinh để phục vụ đời sống của gia đình.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Bê tông dùng trong xây dựng nhà ở được trộn từ những vật liệu nào?","o":["Gạch, ngói, gỗ và sơn","Xi măng, cát, đá (sỏi) và nước","Thép, kính, nhựa và vải","Đất sét, rơm, tre và vôi"],"a":"Xi măng, cát, đá (sỏi) và nước","h":"Nhớ lại vật liệu dùng để đổ móng, cột và dầm của ngôi nhà.","e":"Bê tông là hỗn hợp của xi măng, cát, đá (sỏi) và nước; khi đông cứng lại rất chắc, dùng để làm móng, cột, dầm và sàn nhà.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trình tự nào sau đây đúng với các bước chính khi xây dựng một ngôi nhà ở?","o":["Hoàn thiện nhà, thi công phần thô, chuẩn bị và thiết kế","Thi công phần thô, chuẩn bị và thiết kế, hoàn thiện nhà","Chuẩn bị và thiết kế, thi công phần thô, hoàn thiện nhà","Chuẩn bị và thiết kế, hoàn thiện nhà, thi công phần thô"],"a":"Chuẩn bị và thiết kế, thi công phần thô, hoàn thiện nhà","h":"Trước khi xây phải có bản vẽ thiết kế, còn sơn và lát nền là việc làm sau cùng.","e":"Xây dựng nhà ở gồm ba bước chính theo thứ tự: chuẩn bị (thiết kế bản vẽ, dự trù kinh phí), thi công phần thô (móng, khung, tường, mái) và hoàn thiện (trát, sơn, lát nền, lắp thiết bị).","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Công việc nào sau đây thuộc giai đoạn hoàn thiện khi xây dựng nhà ở?","o":["Đào móng và đổ bê tông cột","Xây tường và lợp mái","Sơn tường, lát nền và lắp đặt thiết bị vệ sinh","Đổ bê tông sàn các tầng"],"a":"Sơn tường, lát nền và lắp đặt thiết bị vệ sinh","h":"Giai đoạn hoàn thiện là lúc ngôi nhà đã có khung, chỉ còn làm đẹp và lắp đặt thiết bị.","e":"Sơn tường, lát nền, lắp cửa và thiết bị vệ sinh là các công việc hoàn thiện; còn làm móng, đổ cột, xây tường, lợp mái thuộc giai đoạn thi công phần thô.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Đèn ở hành lang ngôi nhà thông minh tự sáng lên khi có người đi qua nhờ thiết bị nào?","o":["Công tắc cơ thông thường","Cảm biến chuyển động","Đồng hồ đo điện","Ổ cắm hẹn giờ"],"a":"Cảm biến chuyển động","h":"Thiết bị này có khả năng 'nhận biết' được sự di chuyển của con người.","e":"Cảm biến chuyển động phát hiện sự di chuyển và gửi tín hiệu để hệ thống tự bật đèn khi có người, tắt khi không còn ai, vừa tiện lợi vừa tiết kiệm điện.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi sử dụng ngôi nhà thông minh, gia đình cần lưu ý điều gì?","o":["Chỉ cần lắp đặt một lần, không bao giờ cần kiểm tra hay bảo trì","Có thể dùng thoải mái mà không cần quan tâm đến hoá đơn tiền điện","Cần biết cách sử dụng, đảm bảo nguồn điện và kết nối mạng ổn định, bảo trì hệ thống khi cần","Nên tắt hết các thiết bị thông minh để tránh bị hỏng"],"a":"Cần biết cách sử dụng, đảm bảo nguồn điện và kết nối mạng ổn định, bảo trì hệ thống khi cần","h":"Các thiết bị thông minh hoạt động được nhờ điện và tín hiệu điều khiển từ xa.","e":"Nhà thông minh phụ thuộc vào nguồn điện và mạng kết nối; người dùng cần biết cách vận hành, kiểm tra và bảo trì hệ thống để thiết bị hoạt động ổn định và an toàn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Một bữa ăn hợp lí cần đáp ứng yêu cầu nào sau đây?","o":["Chỉ ăn thật nhiều thịt, cá cho đủ chất đạm","Đủ các nhóm chất dinh dưỡng với tỉ lệ cân đối, gồm nhiều loại thực phẩm khác nhau","Ăn càng nhiều đồ ngọt và đồ chiên rán càng tốt","Chỉ cần ăn no là được, không cần quan tâm đến nhóm chất"],"a":"Đủ các nhóm chất dinh dưỡng với tỉ lệ cân đối, gồm nhiều loại thực phẩm khác nhau","h":"Cơ thể cần cả bốn nhóm chất: bột đường, đạm, béo, vitamin và chất khoáng.","e":"Bữa ăn hợp lí phải cung cấp đủ bốn nhóm chất dinh dưỡng với tỉ lệ cân đối và đa dạng thực phẩm, giúp cơ thể khoẻ mạnh và phát triển tốt.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao trẻ em và thanh thiếu niên đang lớn cần nhiều chất đạm trong khẩu phần ăn?","o":["Vì chất đạm giúp xây dựng và phát triển cơ thể đang lớn lên","Vì ăn chất đạm thì không cần ăn thêm rau và trái cây","Vì chất đạm chỉ có tác dụng làm thức ăn ngon miệng hơn","Vì trẻ em cần chất đạm để thay thế hoàn toàn chất bột đường"],"a":"Vì chất đạm giúp xây dựng và phát triển cơ thể đang lớn lên","h":"Chất đạm được coi là 'vật liệu' để xây dựng tế bào và cơ bắp của cơ thể.","e":"Nhu cầu dinh dưỡng thay đổi theo lứa tuổi: trẻ em và thanh thiếu niên đang trong giai đoạn phát triển nên cần nhiều chất đạm để xây dựng tế bào, cơ bắp và các tổ chức của cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Phương pháp bảo quản thực phẩm bằng cách làm khô (phơi, sấy) dựa trên nguyên tắc nào?","o":["Cho thêm thật nhiều muối vào thực phẩm","Loại bỏ bớt nước trong thực phẩm để vi sinh vật khó phát triển","Đem thực phẩm đi hun khói thật lâu","Ngâm thực phẩm trong nước lạnh nhiều giờ"],"a":"Loại bỏ bớt nước trong thực phẩm để vi sinh vật khó phát triển","h":"Vi sinh vật gây hỏng thực phẩm cần có nước để sinh sôi và phát triển.","e":"Làm khô lấy đi phần lớn nước trong thực phẩm (như phơi cá, sấy hoa quả) khiến vi sinh vật khó phát triển, nhờ đó thực phẩm giữ được lâu hơn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Bảo quản đông lạnh khác bảo quản lạnh ở điểm nào?","o":["Đông lạnh cần nhiệt độ cao hơn bảo quản lạnh","Đông lạnh giữ thực phẩm ở nhiệt độ rất thấp (khoảng -18°C) nên bảo quản được lâu hơn","Đông lạnh chỉ dùng được cho rau, củ, quả","Đông lạnh không cần dùng đến tủ lạnh hay kho lạnh"],"a":"Đông lạnh giữ thực phẩm ở nhiệt độ rất thấp (khoảng -18°C) nên bảo quản được lâu hơn","h":"Hãy so sánh nhiệt độ của ngăn mát và ngăn đá trong tủ lạnh ở gia đình em.","e":"Bảo quản lạnh giữ thực phẩm ở khoảng 0°C đến 5°C trong ngăn mát, còn bảo quản đông lạnh hạ nhiệt độ xuống khoảng -18°C, làm chậm tối đa sự phát triển của vi sinh vật nên giữ thực phẩm được lâu hơn nhiều.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Món ăn nào sau đây được chế biến theo phương pháp không sử dụng nhiệt?","o":["Canh rau nấu thịt","Cá rán vàng giòn","Nộm (gỏi) rau củ trộn chua ngọt","Thịt kho tàu"],"a":"Nộm (gỏi) rau củ trộn chua ngọt","h":"Phương pháp này làm món ăn bằng cách trộn, ngâm mà không đặt lên bếp đun nấu.","e":"Nộm (gỏi) được chế biến bằng cách trộn các nguyên liệu đã sơ chế với gia vị chua, cay, mặn, ngọt mà không dùng nhiệt; còn nấu canh, rán cá, kho thịt đều phải dùng nhiệt.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Mẹ chuẩn bị nấu một bữa ăn và mua 0,5 kg thịt lợn với giá 140 000 đồng/kg cùng 1 kg rau với giá 20 000 đồng/kg. Tổng số tiền mẹ phải trả là bao nhiêu?","o":["160 000 đồng","90 000 đồng","80 000 đồng","230 000 đồng"],"a":"90 000 đồng","h":"Tính tiền thịt trước: 0,5 kg nhân với 140 000 đồng, rồi cộng thêm tiền rau.","e":"Tiền thịt là 0,5 × 140 000 = 70 000 đồng; tiền rau là 1 × 20 000 = 20 000 đồng. Tổng chi phí cho bữa ăn là 70 000 + 20 000 = 90 000 đồng.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Khi lựa chọn trang phục theo thời tiết, cách chọn nào sau đây là phù hợp?","o":["Mùa hè mặc áo len dày, tối màu cho nổi bật","Mùa hè mặc quần áo mỏng, sáng màu, thấm hút mồ hôi; mùa đông mặc áo dày, giữ ấm","Mùa đông mặc áo mỏng ngắn tay cho mát mẻ","Mặc giống nhau quanh năm, không cần để ý đến thời tiết"],"a":"Mùa hè mặc quần áo mỏng, sáng màu, thấm hút mồ hôi; mùa đông mặc áo dày, giữ ấm","h":"Trang phục phải giúp cơ thể cảm thấy thoải mái khi trời nóng hoặc trời lạnh.","e":"Chọn trang phục theo thời tiết giúp bảo vệ sức khoẻ: trời nóng nên mặc đồ mỏng, sáng màu, thoáng mát; trời lạnh nên mặc đồ dày, kín đáo để giữ ấm cơ thể.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vải sợi pha được tạo thành bằng cách nào và có ưu điểm gì?","o":["Dệt toàn bộ bằng sợi tre nên vải rất cứng","Pha trộn sợi thiên nhiên với sợi hoá học, kết hợp được ưu điểm của cả hai loại sợi","Nhuộm nhiều màu lên vải hoá học để vải bền màu hơn","Ép nhiều lớp vải mỏng chồng lên nhau để vải dày hơn"],"a":"Pha trộn sợi thiên nhiên với sợi hoá học, kết hợp được ưu điểm của cả hai loại sợi","h":"Chữ 'pha' trong tên gọi gợi ý sự kết hợp của hai loại sợi khác nhau.","e":"Vải sợi pha kết hợp sợi thiên nhiên và sợi hoá học nên vừa thoáng mát, thấm hút mồ hôi như vải thiên nhiên, vừa bền, ít nhàu như vải hoá học.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trước khi giặt quần áo, việc làm nào sau đây là đúng?","o":["Cho tất cả quần áo trắng và quần áo màu vào giặt chung một lần","Phân loại quần áo theo màu sắc và chất liệu vải, lộn mặt trái ra ngoài","Ngâm quần áo trong nước xà phòng vài ngày rồi mới giặt","Vò thật mạnh mọi loại vải để quần áo nhanh sạch"],"a":"Phân loại quần áo theo màu sắc và chất liệu vải, lộn mặt trái ra ngoài","h":"Quần áo màu dễ bị phai màu và mỗi loại vải cần một cách giặt khác nhau.","e":"Phân loại quần áo theo màu sắc và chất vải, lộn mặt trái khi giặt giúp quần áo không bị phai màu, lẫn màu, từ đó bền và đẹp hơn.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trên nhãn quần áo có kí hiệu chậu nước kèm theo số 40. Kí hiệu đó cho em biết điều gì?","o":["Quần áo có giá bán là 40 nghìn đồng","Giặt quần áo bằng nước có nhiệt độ không quá 40°C","Quần áo dành cho người nặng 40 kg","Phơi quần áo trong thời gian 40 phút"],"a":"Giặt quần áo bằng nước có nhiệt độ không quá 40°C","h":"Con số ghi trong kí hiệu giặt thường cho biết nhiệt độ của nước khi giặt.","e":"Kí hiệu chậu nước kèm số 40 hướng dẫn giặt bằng nước ở nhiệt độ tối đa 40°C; giặt bằng nước nóng hơn có thể làm hỏng vải, khiến quần áo bị co hoặc phai màu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trang phục theo phong cách thể thao thường có đặc điểm gì?","o":["Cầu kì, nhiều chi tiết ren và đính đá","Khoẻ khoắn, thoải mái, dễ vận động, thường kết hợp với giày thể thao","Trang trọng, chỉ dùng trong các buổi lễ quan trọng","Mỏng nhẹ, chỉ dùng khi đi ngủ"],"a":"Khoẻ khoắn, thoải mái, dễ vận động, thường kết hợp với giày thể thao","h":"Phong cách này gắn liền với các hoạt động vận động và vui chơi.","e":"Phong cách thể thao mang lại vẻ khoẻ khoắn, năng động; trang phục thường rộng rãi, co giãn, thấm hút mồ hôi và thường đi cùng giày thể thao.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Đối với học sinh, mặc đẹp và phù hợp có nghĩa là gì?","o":["Phải mua quần áo hàng hiệu thật đắt tiền","Chạy theo mọi mốt mới nhất dù không hợp với mình","Trang phục gọn gàng, sạch sẽ, phù hợp lứa tuổi, hoàn cảnh và vóc dáng của bản thân","Mặc càng nhiều phụ kiện nổi bật thì càng đẹp"],"a":"Trang phục gọn gàng, sạch sẽ, phù hợp lứa tuổi, hoàn cảnh và vóc dáng của bản thân","h":"Cái đẹp trong trang phục của học sinh nằm ở sự phù hợp và gọn gàng.","e":"Mặc đẹp không đồng nghĩa với đắt tiền hay chạy theo mốt; học sinh mặc đẹp khi trang phục sạch sẽ, gọn gàng, vừa vặn và phù hợp với lứa tuổi, hoàn cảnh sử dụng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trên một chiếc quạt điện có ghi thông số 220V - 45W. Số 45W cho biết điều gì?","o":["Điện áp định mức của quạt","Công suất định mức của quạt, cho biết mức điện năng quạt tiêu thụ khi hoạt động","Tốc độ quay tối đa của cánh quạt","Khối lượng của chiếc quạt"],"a":"Công suất định mức của quạt, cho biết mức điện năng quạt tiêu thụ khi hoạt động","h":"Kí hiệu W (oát) là đơn vị dùng để đo công suất.","e":"45W là công suất định mức của quạt: khi hoạt động bình thường quạt tiêu thụ công suất khoảng 45 oát; thiết bị có công suất càng lớn thường tiêu thụ càng nhiều điện.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhóm đồ dùng loại điện - cơ gồm những thiết bị nào sau đây?","o":["Đèn LED, đèn huỳnh quang, đèn sợi đốt","Bếp điện, bàn là điện, nồi cơm điện","Quạt điện, máy giặt, máy bơm nước","Bình nóng lạnh, ấm đun nước điện, bếp hồng ngoại"],"a":"Quạt điện, máy giặt, máy bơm nước","h":"Đồ dùng điện - cơ biến đổi điện năng thành cơ năng, tạo ra chuyển động quay.","e":"Quạt điện, máy giặt và máy bơm nước đều có động cơ điện biến điện năng thành cơ năng để quay cánh quạt, lồng giặt hay cánh bơm, nên thuộc nhóm đồ dùng điện - cơ.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Nhược điểm lớn nhất của đèn sợi đốt so với đèn LED là gì?","o":["Ánh sáng của đèn sợi đốt quá mạnh, gây chói mắt","Phần lớn điện năng bị biến thành nhiệt, hiệu suất phát sáng thấp nên rất tốn điện","Đèn sợi đốt có tuổi thọ quá dài, khó thay thế","Đèn sợi đốt không phát ra được ánh sáng màu vàng"],"a":"Phần lớn điện năng bị biến thành nhiệt, hiệu suất phát sáng thấp nên rất tốn điện","h":"Khi chạm vào bóng đèn sợi đốt đang sáng, em sẽ cảm thấy rất nóng.","e":"Đèn sợi đốt chỉ biến một phần nhỏ điện năng thành ánh sáng, phần lớn biến thành nhiệt làm bóng đèn nóng lên, nên hao phí nhiều điện và tuổi thọ cũng thấp hơn hẳn đèn LED.","t":"cn-lop6","g":6,"l":"thu-thach"},{"p":"Trên một bóng đèn có ghi 220V - 9W. Con số 220V có ý nghĩa gì?","o":["Đèn dùng được với mọi nguồn điện tuỳ ý","Đó là điện áp định mức, đèn hoạt động bình thường khi mắc vào nguồn điện 220V","Đèn có thể phát sáng liên tục trong 220 giờ","Đèn có công suất là 220 oát"],"a":"Đó là điện áp định mức, đèn hoạt động bình thường khi mắc vào nguồn điện 220V","h":"Kí hiệu V (vôn) là đơn vị dùng để đo điện áp.","e":"220V là điện áp định mức của đèn: mắc đèn vào nguồn điện 220V như điện lưới trong gia đình thì đèn sáng bình thường; nếu dùng điện áp cao hơn quy định, đèn dễ bị hỏng.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong nồi cơm điện, bộ phận sinh nhiệt có nhiệm vụ gì?","o":["Giữ cho vỏ nồi luôn mát khi nấu","Biến đổi điện năng thành nhiệt năng để làm chín cơm","Đo lượng nước cần cho vào nồi","Tự động mở nắp khi cơm đã chín"],"a":"Biến đổi điện năng thành nhiệt năng để làm chín cơm","h":"Tên gọi của bộ phận này đã nói lên công việc mà nó đảm nhiệm.","e":"Bộ phận sinh nhiệt (mâm nhiệt) chuyển hoá điện năng thành nhiệt năng rồi truyền nhiệt vào nồi nấu để làm chín cơm, đây là bộ phận quan trọng trong quá trình nấu.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Bếp hồng ngoại làm chín thức ăn theo nguyên lí nào?","o":["Tạo dòng điện cảm ứng ngay trong đáy nồi như bếp từ","Bộ phận sinh nhiệt làm nóng mặt bếp, nhiệt truyền qua đáy nồi để nấu chín thức ăn","Đốt cháy khí gas để tạo thành ngọn lửa","Dùng sóng âm để làm nóng thức ăn"],"a":"Bộ phận sinh nhiệt làm nóng mặt bếp, nhiệt truyền qua đáy nồi để nấu chín thức ăn","h":"Sau khi nấu xong, mặt bếp hồng ngoại vẫn còn nóng ran trong một lúc lâu.","e":"Bếp hồng ngoại dùng bộ phận sinh nhiệt (mâm nhiệt hoặc bóng halogen) phát nhiệt làm nóng mặt bếp và đáy nồi đặt trên đó, nhiệt truyền vào làm chín thức ăn; vì vậy bếp dùng được với nhiều loại nồi khác nhau.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Thói quen nào sau đây giúp gia đình tiết kiệm điện khi sử dụng điều hoà nhiệt độ?","o":["Đặt nhiệt độ xuống 16°C và mở cửa phòng cho thoáng","Bật điều hoà cả ngày kể cả khi không có người ở nhà","Đặt nhiệt độ từ 26°C trở lên và đóng kín cửa khi sử dụng","Tắt điều hoà rồi bật lại liên tục nhiều lần trong ngày"],"a":"Đặt nhiệt độ từ 26°C trở lên và đóng kín cửa khi sử dụng","h":"Nhiệt độ đặt càng thấp, điều hoà càng phải làm việc nhiều và càng tốn điện.","e":"Đặt điều hoà ở mức từ 26°C trở lên, đóng kín cửa để giữ hơi lạnh và tắt khi ra khỏi phòng là những thói quen đơn giản giúp tiết kiệm điện rõ rệt.","t":"cn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trồng trọt có vai trò nào sau đây đối với đời sống và sản xuất?","o":["Cung cấp lương thực, thực phẩm cho con người và nguyên liệu cho công nghiệp chế biến","Chỉ dùng để trang trí, làm cảnh trong gia đình","Chỉ cung cấp thức ăn cho vật nuôi trong chăn nuôi","Làm cạn kiệt nguồn nước và đất canh tác"],"a":"Cung cấp lương thực, thực phẩm cho con người và nguyên liệu cho công nghiệp chế biến","h":"Trồng trọt là ngành sản xuất chính của nông nghiệp.","e":"Trồng trọt cung cấp lương thực, thực phẩm cho con người, thức ăn cho chăn nuôi và nguyên liệu cho công nghiệp chế biến, hàng hoá xuất khẩu.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Giống cây trồng tốt cần có những đặc điểm nào sau đây?","o":["Chỉ cần cho quả to, màu sắc đẹp","Sinh trưởng tốt, năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh","Chỉ cần mọc nhanh, không cần năng suất","Phải là giống mua từ nước ngoài về"],"a":"Sinh trưởng tốt, năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh","h":"Hãy nghĩ đến mục đích cuối cùng khi chọn giống để gieo trồng.","e":"Giống tốt phải sinh trưởng, phát triển tốt trong điều kiện ngoại cảnh nhất định, cho năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh hại.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Đất trồng gồm những thành phần chính nào?","o":["Chỉ gồm chất khoáng và chất hữu cơ","Phần rắn và phần lỏng, không có phần khí","Phần rắn, phần lỏng và phần khí","Chỉ gồm nước và không khí"],"a":"Phần rắn, phần lỏng và phần khí","h":"Đất trồng không chỉ là phần đất khô mà ta nhìn thấy.","e":"Đất trồng gồm ba thành phần: phần rắn (chất khoáng và chất hữu cơ), phần lỏng (nước trong đất) và phần khí (không khí trong đất).","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Gieo trồng đúng thời vụ mang lại lợi ích gì cho cây trồng?","o":["Cây không cần chăm sóc nữa","Tiết kiệm được toàn bộ phân bón","Cây cho thu hoạch quanh năm","Cây sinh trưởng, phát triển tốt, hạn chế được sâu, bệnh và thời tiết bất lợi"],"a":"Cây sinh trưởng, phát triển tốt, hạn chế được sâu, bệnh và thời tiết bất lợi","h":"Mỗi loại cây chỉ thích hợp gieo trồng vào một khoảng thời gian nhất định trong năm.","e":"Gieo trồng đúng thời vụ giúp cây trồng sinh trưởng, phát triển tốt, tránh được sâu, bệnh hại và các điều kiện thời tiết bất lợi, cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nên tưới nước cho cây trồng vào thời điểm nào trong ngày là tốt nhất?","o":["Vào giữa trưa nắng gắt","Vào lúc trời đang mưa to","Vào bất kì lúc nào, không có sự khác biệt","Vào sáng sớm hoặc chiều mát"],"a":"Vào sáng sớm hoặc chiều mát","h":"Tưới nước lúc trời nắng gắt dễ làm cây bị sốc nhiệt và nước bốc hơi nhanh.","e":"Tưới nước vào sáng sớm hoặc chiều mát giúp cây hấp thụ nước tốt, tránh lãng phí nước do bốc hơi và hạn chế cây bị sốc nhiệt, cháy lá.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Bón phân hữu cơ cho đất trồng có tác dụng gì?","o":["Làm đất chai cứng và bạc màu nhanh","Tiêu diệt toàn bộ vi sinh vật trong đất","Làm đất tơi xốp, tăng độ phì nhiêu cho đất","Chỉ giúp lá cây xanh đẹp tạm thời"],"a":"Làm đất tơi xốp, tăng độ phì nhiêu cho đất","h":"Phân hữu cơ có nguồn gốc từ phân chuồng, phân xanh, rác thải hữu cơ hoai mục.","e":"Phân hữu cơ giúp cải tạo đất, làm đất tơi xốp, tăng độ phì nhiêu và cung cấp chất dinh dưỡng cho cây trồng một cách lâu dài.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Làm cỏ, vun xới cho cây trồng có tác dụng gì?","o":["Làm cho cây trồng nhanh bị héo úa","Diệt cỏ dại, làm đất tơi xốp, giúp bộ rễ phát triển và hạn chế nơi trú ẩn của sâu, bệnh","Chỉ nhằm làm cho luống cây trông đẹp hơn","Làm giảm mạnh độ ẩm của đất"],"a":"Diệt cỏ dại, làm đất tơi xốp, giúp bộ rễ phát triển và hạn chế nơi trú ẩn của sâu, bệnh","h":"Cỏ dại cạnh tranh nước và chất dinh dưỡng với cây trồng.","e":"Làm cỏ, vun xới giúp diệt cỏ dại, phá váng mặt đất, làm đất tơi xốp để rễ cây hô hấp và hút chất dinh dưỡng tốt, đồng thời hạn chế sâu, bệnh hại.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Biện pháp phòng trừ sâu, bệnh hại nào sau đây an toàn cho con người và thân thiện với môi trường?","o":["Sử dụng thiên địch, bẫy sinh học và giống cây chống chịu sâu, bệnh","Phun thuốc hoá học với liều lượng càng cao càng tốt","Phun thuốc hoá học ngay trước ngày thu hoạch","Trộn nhiều loại thuốc hoá học với nhau khi phun"],"a":"Sử dụng thiên địch, bẫy sinh học và giống cây chống chịu sâu, bệnh","h":"Hãy nghĩ đến biện pháp phòng trừ tổng hợp, ưu tiên biện pháp sinh học.","e":"Phòng trừ tổng hợp ưu tiên biện pháp canh tác, giống chống chịu và biện pháp sinh học (thiên địch, bẫy) để bảo vệ môi trường, an toàn cho người và sản phẩm.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thu hoạch nông sản đúng thời điểm có tác dụng gì?","o":["Đảm bảo được số lượng và chất lượng của nông sản","Làm nông sản nhanh bị hư hỏng hơn","Làm giảm năng suất của cây trồng","Làm tăng chi phí bảo quản nông sản"],"a":"Đảm bảo được số lượng và chất lượng của nông sản","h":"Thu hoạch quá sớm hay quá muộn đều ảnh hưởng đến sản phẩm thu được.","e":"Thu hoạch đúng độ chín, đúng thời điểm giúp nông sản đạt số lượng và chất lượng cao nhất, tránh rơi rụng, hư hỏng, giảm tổn thất sau thu hoạch.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sau khi thu hoạch, thóc cần được bảo quản như thế nào để không bị ẩm mốc, mối mọt?","o":["Đổ thành đống ngay khi thóc còn ướt","Để ngoài sân nhiều ngày cho tự khô","Phơi hoặc sấy khô rồi cất giữ ở nơi khô ráo, thoáng mát","Trộn lẫn thóc với phân bón để chống mọt"],"a":"Phơi hoặc sấy khô rồi cất giữ ở nơi khô ráo, thoáng mát","h":"Độ ẩm cao là điều kiện để nấm mốc và mối mọt phát triển.","e":"Thóc sau thu hoạch phải được phơi hoặc sấy khô đến độ ẩm an toàn, làm sạch rồi bảo quản ở nơi khô ráo, thoáng mát để tránh ẩm mốc và mối mọt.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi chọn giống vật nuôi, nên chọn những con giống có đặc điểm nào?","o":["Con nào có giá rẻ nhất thì chọn","Khoẻ mạnh, nguồn gốc rõ ràng, phù hợp với mục đích chăn nuôi","Chỉ cần to con, không cần khoẻ mạnh","Chọn con đang ốm yếu để được giảm giá"],"a":"Khoẻ mạnh, nguồn gốc rõ ràng, phù hợp với mục đích chăn nuôi","h":"Giống tốt là yếu tố quan trọng quyết định năng suất chăn nuôi.","e":"Vật nuôi giống phải khoẻ mạnh, không bệnh tật, có nguồn gốc rõ ràng và phù hợp với mục đích nuôi (lấy thịt, lấy trứng, lấy sữa...) thì mới cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Thức ăn cho gà cần đảm bảo yêu cầu nào sau đây?","o":["Chỉ cần cho ăn thóc là đủ","Càng trộn nhiều muối càng tốt","Cho ăn thức ăn đã ôi thiu để tiết kiệm","Đủ năng lượng, protein, chất khoáng và vitamin"],"a":"Đủ năng lượng, protein, chất khoáng và vitamin","h":"Gà ở mỗi giai đoạn sinh trưởng cần khẩu phần ăn cân đối các chất dinh dưỡng.","e":"Thức ăn cho gà phải đảm bảo đủ và cân đối năng lượng, protein, chất khoáng và vitamin thì gà mới sinh trưởng, phát triển tốt và cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chuồng nuôi vật nuôi cần được vệ sinh như thế nào?","o":["Chỉ dọn dẹp khi chuồng đã có mùi hôi nặng","Thường xuyên quét dọn, khử trùng, giữ chuồng luôn khô ráo, sạch sẽ","Không cần dọn phân, chỉ cần cho ăn đầy đủ","Giữ chuồng luôn ẩm ướt để vật nuôi mát"],"a":"Thường xuyên quét dọn, khử trùng, giữ chuồng luôn khô ráo, sạch sẽ","h":"Chuồng bẩn là nơi mầm bệnh dễ phát sinh và lây lan.","e":"Vệ sinh chuồng trại thường xuyên (quét dọn, rửa, khử trùng, giữ khô ráo) giúp vật nuôi khoẻ mạnh, hạn chế mầm bệnh và ô nhiễm môi trường.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Biện pháp nào sau đây giúp phòng bệnh hiệu quả cho vật nuôi?","o":["Chỉ chữa trị khi vật nuôi đã mắc bệnh nặng","Cho vật nuôi uống thuốc chữa bệnh của người","Cách li những con vật nuôi khoẻ mạnh khỏi đàn","Tiêm phòng vắc-xin đầy đủ và đúng lịch cho vật nuôi"],"a":"Tiêm phòng vắc-xin đầy đủ và đúng lịch cho vật nuôi","h":"Phòng bệnh luôn tốt hơn và rẻ hơn chữa bệnh.","e":"Tiêm phòng vắc-xin đầy đủ, đúng lịch kết hợp vệ sinh chuồng trại và chăm sóc tốt là biện pháp phòng bệnh chủ động, hiệu quả nhất cho vật nuôi.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chuồng nuôi lợn cần đảm bảo điều kiện nào sau đây?","o":["Thông thoáng, ấm về mùa đông, mát về mùa hè, tránh gió lùa và mưa hắt","Kín mít, không cần cửa thông gió","Luôn ẩm ướt, nền chuồng đầy bùn","Càng chật hẹp càng tốt để lợn ít vận động"],"a":"Thông thoáng, ấm về mùa đông, mát về mùa hè, tránh gió lùa và mưa hắt","h":"Môi trường chuồng nuôi ảnh hưởng trực tiếp đến sức khoẻ của lợn.","e":"Chuồng nuôi lợn phải cao ráo, thông thoáng, tránh gió lùa, mưa hắt; ấm về mùa đông, mát về mùa hè thì lợn mới khoẻ mạnh, ít bệnh và lớn nhanh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để bảo vệ môi trường trong chăn nuôi, chất thải của vật nuôi nên được xử lí bằng cách nào?","o":["Xả thẳng ra sông, suối gần nhà","Đổ ra đường đi chung của xóm","Ủ làm phân bón hữu cơ hoặc đưa vào hầm biogas","Để nguyên trong chuồng, không cần xử lí"],"a":"Ủ làm phân bón hữu cơ hoặc đưa vào hầm biogas","h":"Chất thải chăn nuôi nếu xử lí đúng cách sẽ thành nguồn phân bón và chất đốt có ích.","e":"Ủ chất thải làm phân hữu cơ hoặc xử lí bằng hầm biogas vừa giảm ô nhiễm môi trường, vừa tạo phân bón cho cây trồng và khí đốt phục vụ sinh hoạt.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nhóm thức ăn nào sau đây giàu protein, thích hợp bổ sung cho vật nuôi?","o":["Rơm rạ, cỏ khô","Ngô, sắn, khoai lang","Đậu tương, bột cá, bột thịt","Muối khoáng và nước uống"],"a":"Đậu tương, bột cá, bột thịt","h":"Protein là chất dinh dưỡng giúp vật nuôi tạo thịt, trứng, sữa.","e":"Các thức ăn như đậu tương, bột cá, bột thịt, khô dầu chứa nhiều protein; trong khi ngô, sắn chủ yếu cung cấp năng lượng, rơm rạ nhiều chất xơ.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Máng ăn và máng uống cho vật nuôi cần được chăm sóc như thế nào?","o":["Rửa sạch thường xuyên, nước uống luôn sạch và đầy đủ","Để thức ăn thừa đọng lại nhiều ngày","Không cần rửa, chỉ cần thêm thức ăn mới lên trên","Dùng chung máng cho cả vật nuôi bệnh và khoẻ mà không khử trùng"],"a":"Rửa sạch thường xuyên, nước uống luôn sạch và đầy đủ","h":"Thức ăn, nước uống bẩn là đường lây bệnh cho vật nuôi.","e":"Máng ăn, máng uống phải được rửa sạch thường xuyên; thức ăn thừa phải dọn bỏ, nước uống luôn sạch thì vật nuôi mới ăn uống tốt và ít mắc bệnh đường tiêu hoá.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trước khi thả cá giống, ao nuôi cần được xử lí như thế nào?","o":["Thả cá ngay vào ao cũ, không cần xử lí","Đổ thật nhiều phân tươi xuống ao","Để ao đầy cỏ dại, rác và cá tạp","Tát cạn, vét bùn, bón vôi khử trùng, phơi đáy ao rồi mới lấy nước sạch vào"],"a":"Tát cạn, vét bùn, bón vôi khử trùng, phơi đáy ao rồi mới lấy nước sạch vào","h":"Ao nuôi chưa xử lí còn chứa mầm bệnh và địch hại của cá.","e":"Chuẩn bị ao nuôi gồm: tát cạn, vét bớt bùn đáy, bón vôi khử trùng, phơi đáy ao, diệt cá tạp, địch hại rồi mới cấp nước sạch vào ao để thả cá giống.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi cho cá ăn, cần đảm bảo nguyên tắc nào sau đây?","o":["Cho ăn càng nhiều càng tốt để cá mau lớn","Đúng lượng, đúng giờ, đúng vị trí và thức ăn đảm bảo chất lượng","Cho ăn vào giữa trưa nắng gắt","Thay đổi giờ cho ăn liên tục mỗi ngày"],"a":"Đúng lượng, đúng giờ, đúng vị trí và thức ăn đảm bảo chất lượng","h":"Cho ăn thừa sẽ làm ô nhiễm nước ao và lãng phí thức ăn.","e":"Cho cá ăn đúng lượng, đúng giờ, đúng vị trí cố định giúp cá ăn hết thức ăn, lớn đều, đồng thời tránh thừa thức ăn gây ô nhiễm nước ao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nước ao nuôi cá được coi là tốt khi có màu nào sau đây?","o":["Màu đen, có mùi hôi thối","Màu xanh nõn chuối","Màu đỏ gạch, nổi váng dày","Trong veo hoàn toàn như nước uống"],"a":"Màu xanh nõn chuối","h":"Màu nước ao thể hiện sự phát triển của các sinh vật phù du làm thức ăn tự nhiên cho cá.","e":"Nước ao có màu xanh nõn chuối chứng tỏ tảo lục và sinh vật phù du phát triển thích hợp, tạo nguồn thức ăn tự nhiên và ôxi cho cá; nước đen, đỏ gạch là dấu hiệu nước bị ô nhiễm.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thả cá với mật độ quá dày sẽ gây ra hậu quả gì?","o":["Cá lớn nhanh hơn bình thường","Tiết kiệm được nhiều thức ăn","Cá chậm lớn, thiếu ôxi và dễ phát sinh dịch bệnh","Nước ao luôn trong và sạch hơn"],"a":"Cá chậm lớn, thiếu ôxi và dễ phát sinh dịch bệnh","h":"Ao nuôi chỉ nuôi được một lượng cá nhất định phù hợp với diện tích và độ sâu của ao.","e":"Mật độ thả quá dày làm cá cạnh tranh thức ăn và ôxi, chất thải nhiều khiến nước ao ô nhiễm, cá chậm lớn và dễ bùng phát dịch bệnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Người ta thường áp dụng những phương pháp nào để chọn tạo giống cây trồng mới?","o":["Chỉ bón thật nhiều phân cho cây","Chọn lọc và lai","Trồng cây ở càng nhiều nơi càng tốt","Thu hoạch sớm hơn bình thường"],"a":"Chọn lọc và lai","h":"Các nhà chọn giống thường kết hợp những cây bố, mẹ có đặc tính tốt với nhau.","e":"Chọn tạo giống cây trồng thường dùng phương pháp chọn lọc (chọn cây tốt làm giống) và lai (lai hai giống khác nhau) để tạo giống mới có năng suất cao, chất lượng tốt và chống chịu được sâu, bệnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Theo mục đích sử dụng, cây trồng ở nước ta được phân thành các nhóm nào sau đây?","o":["Cây thân gỗ, cây thân thảo, cây thân leo và cây thân bụi","Cây lương thực, cây thực phẩm, cây ăn quả, cây công nghiệp, cây lấy gỗ, cây hoa và cây cảnh","Cây ưa sáng, cây ưa bóng, cây chịu hạn và cây chịu úng","Cây trồng trên cạn, cây trồng dưới nước và cây trồng trên giàn"],"a":"Cây lương thực, cây thực phẩm, cây ăn quả, cây công nghiệp, cây lấy gỗ, cây hoa và cây cảnh","h":"Hãy nhớ cách phân loại dựa vào việc cây trồng được dùng để làm gì.","e":"Theo mục đích sử dụng, cây trồng gồm các nhóm: cây lương thực, cây thực phẩm, cây ăn quả, cây công nghiệp, cây lấy gỗ, cây hoa và cây cảnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Làm đất trồng cây nhằm mục đích chính nào sau đây?","o":["Làm cho đất ngày càng cứng và chặt lại","Làm đất tơi xốp, thoáng khí, tiêu diệt cỏ dại và mầm mống sâu, bệnh, tạo điều kiện tốt cho cây trồng sinh trưởng","Làm tăng độ chua của đất để cây dễ hút chất dinh dưỡng","Làm cho đất mất hết các vi sinh vật có ích"],"a":"Làm đất tơi xốp, thoáng khí, tiêu diệt cỏ dại và mầm mống sâu, bệnh, tạo điều kiện tốt cho cây trồng sinh trưởng","h":"Đất tơi xốp, thoáng khí thì bộ rễ cây mới dễ phát triển.","e":"Làm đất giúp đất tơi xốp, thoáng khí, vùi lấp và tiêu diệt cỏ dại cùng mầm mống sâu, bệnh, tạo điều kiện thuận lợi cho cây trồng sinh trưởng và phát triển.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nhóm công việc nào sau đây thuộc khâu làm đất trồng cây?","o":["Gieo hạt, trồng cây con và tưới nước","Làm cỏ, bón phân và phòng trừ sâu, bệnh","Cày đất, bừa và đập đất, lên luống","Thu hoạch, phơi sấy và cất giữ nông sản"],"a":"Cày đất, bừa và đập đất, lên luống","h":"Đây là những công việc phải hoàn thành trước khi gieo trồng.","e":"Các công việc làm đất gồm cày đất, bừa và đập đất, lên luống (đối với cây trồng cần lên luống) nhằm chuẩn bị đất thật tốt cho việc gieo trồng.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để cải tạo đất chua, biện pháp thường được sử dụng là gì?","o":["Bón vôi bột cho đất","Bón thật nhiều phân đạm hoá học","Giữ nước ngập ruộng quanh năm","Trồng một loại cây liên tiếp trong nhiều năm"],"a":"Bón vôi bột cho đất","h":"Vôi có tính kiềm, giúp trung hoà độ chua của đất.","e":"Bón vôi là biện pháp phổ biến để khử chua, cải tạo đất chua, đồng thời bổ sung thêm canxi cho đất và cây trồng.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thời vụ gieo trồng của mỗi loại cây trồng được xác định dựa vào những yếu tố nào sau đây?","o":["Giá bán của nông sản trên thị trường","Khí hậu của địa phương, đặc điểm của cây trồng và tình hình sâu, bệnh","Số lao động hiện có của gia đình","Diện tích đất canh tác nhiều hay ít"],"a":"Khí hậu của địa phương, đặc điểm của cây trồng và tình hình sâu, bệnh","h":"Mỗi loại cây chỉ sinh trưởng tốt trong điều kiện thời tiết nhất định.","e":"Thời vụ gieo trồng được xác định dựa vào khí hậu, thời tiết của địa phương, đặc điểm sinh trưởng của cây trồng và tình hình phát sinh sâu, bệnh hại ở địa phương.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Công việc tỉa, dặm cây khi chăm sóc cây trồng nhằm mục đích gì?","o":["Làm cho ruộng cây trông gọn gàng, đẹp mắt hơn","Giúp cây trồng không cần bón phân trong suốt vụ","Loại bỏ cây yếu, cây bị sâu, bệnh và trồng bổ sung vào chỗ cây chết để đảm bảo mật độ","Làm tăng số lượng cỏ dại để giữ ẩm cho đất"],"a":"Loại bỏ cây yếu, cây bị sâu, bệnh và trồng bổ sung vào chỗ cây chết để đảm bảo mật độ","h":"Ruộng cây cần có mật độ đều và đủ số cây trên một diện tích.","e":"Tỉa bỏ cây yếu, cây bị sâu, bệnh và dặm cây khoẻ vào chỗ cây chết giúp ruộng có mật độ hợp lí, cây sinh trưởng đồng đều và cho năng suất cao.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phòng trừ tổng hợp sâu, bệnh hại cây trồng là biện pháp như thế nào?","o":["Chỉ sử dụng thuốc hoá học với liều cao để diệt sâu, bệnh nhanh nhất","Phối hợp nhiều biện pháp như canh tác, dùng giống chống chịu, biện pháp sinh học và hoá học hợp lí","Chỉ bắt sâu bằng tay, không dùng thêm bất kì biện pháp nào khác","Không phòng trừ, để cây tự chống chịu sâu, bệnh"],"a":"Phối hợp nhiều biện pháp như canh tác, dùng giống chống chịu, biện pháp sinh học và hoá học hợp lí","h":"Từ khoá quan trọng là 'tổng hợp' – kết hợp nhiều biện pháp với nhau.","e":"Phòng trừ tổng hợp là phối hợp các biện pháp canh tác, giống chống chịu, sinh học, cơ giới và hoá học (chỉ dùng khi cần thiết, đúng liều lượng) để phòng trừ sâu, bệnh hiệu quả mà vẫn an toàn cho con người và môi trường.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Thu hoạch sản phẩm trồng trọt thường được thực hiện bằng những phương pháp nào sau đây?","o":["Cày, bừa, lên luống và san phẳng mặt ruộng","Tưới nước, bón phân, làm cỏ và vun xới","Phơi, sấy, đóng gói và vận chuyển","Hái, nhổ, đào và cắt tuỳ thuộc vào loại cây trồng"],"a":"Hái, nhổ, đào và cắt tuỳ thuộc vào loại cây trồng","h":"Mỗi loại cây có bộ phận thu hoạch và cách thu hái khác nhau.","e":"Tuỳ loại cây trồng, người ta thu hoạch bằng cách hái (rau, quả), nhổ (lạc, một số rau), đào (khoai, sắn) hoặc cắt (lúa, ngô) để đảm bảo số lượng và chất lượng nông sản.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vì sao rau, quả tươi thường được bảo quản trong kho lạnh?","o":["Nhiệt độ thấp làm chậm quá trình hô hấp và hạn chế vi sinh vật gây hỏng, giúp rau, quả tươi lâu","Nhiệt độ thấp làm rau, quả tăng thêm nhiều chất dinh dưỡng","Kho lạnh giúp rau, quả chín nhanh và đều hơn","Nhiệt độ thấp diệt được mọi loại sâu bám trên rau, quả"],"a":"Nhiệt độ thấp làm chậm quá trình hô hấp và hạn chế vi sinh vật gây hỏng, giúp rau, quả tươi lâu","h":"Hãy nghĩ đến nguyên nhân làm rau, quả nhanh bị hỏng sau khi thu hoạch.","e":"Ở nhiệt độ thấp, quá trình hô hấp của rau, quả và hoạt động của vi sinh vật gây hỏng đều bị kìm hãm, nên rau, quả giữ được tươi ngon lâu hơn.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nhân giống cây trồng bằng phương pháp giâm cành được thực hiện như thế nào?","o":["Gieo hạt của cây xuống đất ẩm để hạt nảy mầm thành cây con","Khoanh vỏ một cành trên cây mẹ, bó đất cho ra rễ rồi cắt xuống trồng","Cắt một đoạn cành có đủ mắt, chồi, cắm xuống đất ẩm để cành ra rễ và phát triển thành cây mới","Lấy mắt của cây này gắn chặt vào gốc của cây khác"],"a":"Cắt một đoạn cành có đủ mắt, chồi, cắm xuống đất ẩm để cành ra rễ và phát triển thành cây mới","h":"Tên phương pháp gắn liền với việc cắm cành xuống đất.","e":"Giâm cành là cắt đoạn cành có đủ mắt, chồi rồi cắm xuống đất ẩm để cành ra rễ, phát triển thành cây mới. Phương pháp này thường áp dụng với cây sắn, mía, khoai lang, hoa hồng.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ưu điểm nổi bật của phương pháp chiết cành là gì?","o":["Tạo được số lượng cây giống rất lớn trong thời gian ngắn","Cây con giữ được đặc tính tốt của cây mẹ và sớm cho thu hoạch (cho quả)","Cây con có bộ rễ rất khoẻ, không cần chăm sóc gì thêm","Có thể áp dụng được cho mọi loại cây trồng"],"a":"Cây con giữ được đặc tính tốt của cây mẹ và sớm cho thu hoạch (cho quả)","h":"Cành chiết được lấy từ cây mẹ tốt và đã trưởng thành.","e":"Chiết cành giúp cây con giữ nguyên đặc tính tốt của cây mẹ và sớm cho quả vì cành chiết đã trưởng thành; tuy nhiên số lượng cây giống tạo được ít và nếu chiết nhiều sẽ ảnh hưởng đến cây mẹ.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong phương pháp ghép cây, gốc ghép có vai trò nào sau đây?","o":["Là bộ phận cho quả chính, quyết định chất lượng quả của cây ghép","Cung cấp bộ rễ hút nước và chất dinh dưỡng để nuôi cành ghép, mắt ghép phát triển","Giúp cây ghép không cần tưới nước và bón phân","Chỉ có tác dụng giữ cho cây đứng vững trên mặt đất"],"a":"Cung cấp bộ rễ hút nước và chất dinh dưỡng để nuôi cành ghép, mắt ghép phát triển","h":"Hãy phân biệt vai trò của gốc ghép với cành ghép, mắt ghép.","e":"Gốc ghép cung cấp bộ rễ khoẻ để hút nước và chất dinh dưỡng; cành ghép hoặc mắt ghép mang đặc tính tốt về năng suất, chất lượng của giống cần nhân. Ghép cây giúp kết hợp được ưu điểm của cả hai phần.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Rau được công nhận là rau an toàn khi đạt yêu cầu nào sau đây?","o":["Rau có lá to, màu xanh thật đậm và không có vết sâu nào","Rau được bón càng nhiều phân đạm càng tốt cho mau lớn","Dư lượng thuốc bảo vệ thực vật, hoá chất độc hại và vi sinh vật gây bệnh ở dưới ngưỡng cho phép","Rau được phun thuốc trừ sâu liên tục đến sát ngày thu hoạch"],"a":"Dư lượng thuốc bảo vệ thực vật, hoá chất độc hại và vi sinh vật gây bệnh ở dưới ngưỡng cho phép","h":"Rau an toàn là rau không gây hại cho sức khoẻ của người ăn.","e":"Rau an toàn là rau có dư lượng thuốc bảo vệ thực vật, hoá chất độc hại, kim loại nặng và vi sinh vật gây bệnh ở mức cho phép, không gây hại cho sức khoẻ người tiêu dùng.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Rừng có vai trò quan trọng nào sau đây đối với môi trường và đời sống con người?","o":["Chỉ cung cấp gỗ để làm nhà và đồ dùng","Làm tăng tốc độ xói mòn và rửa trôi đất","Điều hoà khí hậu, giữ đất, chống xói mòn, bảo vệ nguồn nước và là nơi cư trú của nhiều loài sinh vật","Làm cho khí hậu trở nên khô và nóng hơn"],"a":"Điều hoà khí hậu, giữ đất, chống xói mòn, bảo vệ nguồn nước và là nơi cư trú của nhiều loài sinh vật","h":"Rừng được ví như 'lá phổi xanh' của Trái Đất.","e":"Rừng giúp điều hoà khí hậu, hấp thụ khí cacbonic, nhả khí ôxi, giữ đất, chống xói mòn và lũ lụt, bảo vệ nguồn nước và là môi trường sống của nhiều loài động vật, thực vật.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Căn cứ vào mục đích sử dụng, rừng ở nước ta được chia thành những loại nào sau đây?","o":["Rừng tự nhiên, rừng trồng và rừng tái sinh","Rừng lá rộng, rừng lá kim và rừng hỗn giao","Rừng phòng hộ, rừng đặc dụng và rừng sản xuất","Rừng giàu, rừng trung bình và rừng nghèo kiệt"],"a":"Rừng phòng hộ, rừng đặc dụng và rừng sản xuất","h":"Có ba loại rừng chính xét theo mục đích sử dụng chủ yếu.","e":"Theo mục đích sử dụng, rừng gồm: rừng phòng hộ (bảo vệ nguồn nước, bảo vệ đất, chống thiên tai), rừng đặc dụng (bảo tồn thiên nhiên, nghiên cứu khoa học) và rừng sản xuất (kinh doanh gỗ và các lâm sản).","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Thành phần nào sau đây KHÔNG phải là thành phần của rừng?","o":["Cây rừng, cây bụi và thảm thực vật trong rừng","Động vật rừng sinh sống trong rừng","Vi sinh vật sống trong đất rừng","Các công trình xây dựng kiên cố của con người"],"a":"Các công trình xây dựng kiên cố của con người","h":"Rừng là một hệ sinh thái gồm các sinh vật và môi trường sống tự nhiên của chúng.","e":"Rừng gồm quần xã sinh vật rừng (thực vật, động vật, vi sinh vật) sống trong môi trường rừng như đất, nước, khí hậu. Các công trình xây dựng của con người không thuộc thành phần của rừng.","t":"cn-lop7","g":7,"l":"thu-thach"},{"p":"Ở các tỉnh miền Bắc nước ta, rừng thường được trồng chủ yếu vào thời vụ nào?","o":["Mùa xuân và mùa thu","Giữa mùa hè nắng nóng nhất","Mùa đông khô lạnh, ít mưa","Bất kì tháng nào trong năm, không phụ thuộc thời tiết"],"a":"Mùa xuân và mùa thu","h":"Cây rừng mới trồng cần thời tiết ấm áp, đất đủ ẩm để bén rễ.","e":"Ở miền Bắc, vụ trồng rừng chính là mùa xuân và mùa thu, khi thời tiết ấm áp, có mưa, đất đủ ẩm giúp cây con bén rễ và sinh trưởng tốt. Ở miền Nam, trồng rừng thường tiến hành vào mùa mưa.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sau khi trồng, cây rừng con cần được chăm sóc bằng những công việc nào sau đây?","o":["Không cần chăm sóc vì cây rừng tự sinh trưởng được","Phát quang, làm cỏ, xới đất, vun gốc, bón phân và trồng dặm cây chết","Chặt bỏ toàn bộ cây bụi và thảm cỏ xung quanh gốc cây","Chỉ tưới nước một lần duy nhất ngay sau khi trồng"],"a":"Phát quang, làm cỏ, xới đất, vun gốc, bón phân và trồng dặm cây chết","h":"Cây rừng trong những năm đầu còn yếu, dễ bị cỏ dại lấn át.","e":"Chăm sóc cây rừng sau khi trồng gồm phát quang, làm cỏ, xới đất quanh gốc, vun gốc, bón phân, tưới nước khi khô hạn và trồng dặm thay những cây bị chết để rừng sinh trưởng đồng đều.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để phòng, chống cháy rừng hiệu quả, người dân cần làm gì?","o":["Đốt nương, đốt thực bì gần rừng vào những ngày nắng nóng, hanh khô","Mang lửa vào rừng nấu ăn mà không cần trông coi","Không đốt lửa bừa bãi gần rừng; khi đốt nương phải có người canh và tạo đường băng cản lửa","Chỉ cần dập lửa khi đám cháy đã lan thật rộng"],"a":"Không đốt lửa bừa bãi gần rừng; khi đốt nương phải có người canh và tạo đường băng cản lửa","h":"Phần lớn các vụ cháy rừng đều bắt nguồn từ lửa trong hoạt động của con người lan vào rừng.","e":"Phòng cháy rừng phải bắt đầu từ ý thức của con người: không đốt lửa bừa bãi gần rừng trong mùa khô, đốt nương đúng quy định, có đường băng cản lửa và người canh gác để phát hiện sớm, dập tắt kịp thời khi cháy mới phát sinh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chăn nuôi có vai trò nào sau đây đối với đời sống và sản xuất?","o":["Cung cấp thịt, trứng, sữa cho con người, phân bón cho trồng trọt và nguyên liệu cho công nghiệp chế biến","Chỉ cung cấp sức kéo cho sản xuất nông nghiệp","Thay thế hoàn toàn được ngành trồng trọt","Làm giảm thu nhập và việc làm của người nông dân"],"a":"Cung cấp thịt, trứng, sữa cho con người, phân bón cho trồng trọt và nguyên liệu cho công nghiệp chế biến","h":"Hãy kể những sản phẩm quen thuộc mà chăn nuôi mang lại mỗi ngày.","e":"Chăn nuôi cung cấp thực phẩm giàu dinh dưỡng (thịt, trứng, sữa), sức kéo, phân bón cho trồng trọt và nguyên liệu (da, lông...) cho công nghiệp chế biến, đồng thời tạo thêm thu nhập cho người dân.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phương thức chăn thả trong chăn nuôi có đặc điểm nào sau đây?","o":["Vật nuôi được nuôi hoàn toàn trong chuồng kín với thức ăn công nghiệp","Vật nuôi vừa được chăn thả, vừa được cho ăn thêm tại chuồng","Vật nuôi được thả tự do đi lại và tự tìm kiếm thức ăn trong tự nhiên","Vật nuôi được nuôi trong hệ thống chuồng có điều hoà nhiệt độ"],"a":"Vật nuôi được thả tự do đi lại và tự tìm kiếm thức ăn trong tự nhiên","h":"Tên phương thức gắn với hình ảnh đàn vật nuôi đi ăn trên đồng cỏ, nương rẫy.","e":"Chăn thả là phương thức mà vật nuôi được thả tự do, tự kiếm thức ăn trong tự nhiên; chi phí thấp nhưng năng suất chưa cao và khó kiểm soát dịch bệnh. Ngược lại, nuôi nhốt giữ vật nuôi trong chuồng và cung cấp toàn bộ thức ăn, nước uống.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi nuôi dưỡng vật nuôi đực giống, cần chú ý yêu cầu nào sau đây?","o":["Cho ăn uống đầy đủ chất dinh dưỡng, cho vận động thường xuyên và khai thác phối giống hợp lí","Cho ăn càng ít càng tốt để vật nuôi không bị béo","Nhốt liên tục trong chuồng chật hẹp, không cho vận động","Cho phối giống càng nhiều lần trong ngày càng tốt"],"a":"Cho ăn uống đầy đủ chất dinh dưỡng, cho vận động thường xuyên và khai thác phối giống hợp lí","h":"Đực giống khoẻ mạnh và được khai thác hợp lí mới cho đàn con có chất lượng tốt.","e":"Vật nuôi đực giống cần khẩu phần ăn đầy đủ chất (nhất là protein, chất khoáng, vitamin), được vận động thường xuyên và phối giống đúng mức để duy trì sức khoẻ và cho giống tốt.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi chăm sóc vật nuôi cái sinh sản đang mang thai, cần chú ý điều gì?","o":["Cho ăn ít đi để con sinh ra nhỏ và dễ đẻ","Cho vật nuôi đi cày, kéo nặng như bình thường","Để chuồng trại bẩn và ẩm ướt cho mát","Cho ăn đầy đủ chất dinh dưỡng, giữ chuồng sạch sẽ, yên tĩnh, tránh làm vật nuôi hoảng sợ"],"a":"Cho ăn đầy đủ chất dinh dưỡng, giữ chuồng sạch sẽ, yên tĩnh, tránh làm vật nuôi hoảng sợ","h":"Giai đoạn mang thai quyết định sức khoẻ của cả con mẹ và đàn con sau này.","e":"Vật nuôi cái mang thai cần được ăn uống đầy đủ chất dinh dưỡng, ở trong chuồng sạch sẽ, khô ráo, yên tĩnh, tránh bị hoảng sợ và tránh lao động nặng để con mẹ khoẻ, đàn con sinh ra khoẻ mạnh.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Tiêm vắc-xin cho vật nuôi có tác dụng gì?","o":["Chữa khỏi ngay lập tức mọi bệnh vật nuôi đang mắc","Giúp cơ thể vật nuôi tạo kháng thể để phòng các bệnh truyền nhiễm nguy hiểm","Giúp vật nuôi tăng trọng nhanh hơn bình thường","Thay thế hoàn toàn việc vệ sinh chuồng trại và thức ăn"],"a":"Giúp cơ thể vật nuôi tạo kháng thể để phòng các bệnh truyền nhiễm nguy hiểm","h":"Vắc-xin là biện pháp phòng bệnh chủ động, được dùng trước khi bệnh xảy ra.","e":"Vắc-xin kích thích cơ thể vật nuôi tạo ra kháng thể, giúp vật nuôi chống lại được các bệnh truyền nhiễm nguy hiểm. Vì vậy cần tiêm phòng đầy đủ, đúng lịch và đúng kĩ thuật cho vật nuôi.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi phát hiện một con vật nuôi có dấu hiệu mắc bệnh truyền nhiễm, việc làm nào sau đây là đúng?","o":["Đem bán ngay con vật ốm ra chợ để tránh lây cho đàn","Để con vật ốm ở chung chuồng với đàn cho quen dần","Tự ý cho vật nuôi uống thuốc chữa bệnh của người","Cách li ngay con vật ốm ra khu riêng và báo cho cán bộ thú y để xử lí"],"a":"Cách li ngay con vật ốm ra khu riêng và báo cho cán bộ thú y để xử lí","h":"Bệnh truyền nhiễm lây lan rất nhanh nếu con ốm vẫn ở chung với đàn.","e":"Cách li ngay vật nuôi ốm giúp ngăn mầm bệnh lây lan ra cả đàn; đồng thời cần báo cho cán bộ thú y để chẩn đoán, điều trị và tiến hành vệ sinh, khử trùng chuồng trại.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chăn nuôi gà thịt trong nông hộ đạt hiệu quả khi tuân theo quy trình nào sau đây?","o":["Chuẩn bị chuồng trại, dụng cụ → chọn gà giống tốt → nuôi dưỡng, chăm sóc, phòng bệnh → xuất bán khi gà đạt khối lượng yêu cầu","Mua gà giống → thả tự do hoàn toàn ngoài vườn → bán khi nào có người mua","Xây chuồng thật lớn → nuôi thật đông → không cần tiêm phòng dịch bệnh","Chọn gà giống → chỉ cho ăn một bữa mỗi ngày → nuôi càng lâu càng tốt"],"a":"Chuẩn bị chuồng trại, dụng cụ → chọn gà giống tốt → nuôi dưỡng, chăm sóc, phòng bệnh → xuất bán khi gà đạt khối lượng yêu cầu","h":"Một quy trình chăn nuôi hoàn chỉnh gồm nhiều khâu nối tiếp nhau theo thứ tự.","e":"Quy trình nuôi gà thịt gồm các khâu: chuẩn bị chuồng trại và dụng cụ, chọn con giống khoẻ mạnh, úm gà con, nuôi dưỡng và chăm sóc đúng kĩ thuật, phòng bệnh đầy đủ, rồi xuất bán khi gà đạt khối lượng theo yêu cầu.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ngành thuỷ sản có vai trò nào sau đây đối với đời sống và kinh tế?","o":["Chỉ cung cấp cá để nuôi làm cảnh trong gia đình","Cung cấp thực phẩm giàu đạm cho con người và nguyên liệu cho xuất khẩu, công nghiệp chế biến","Thay thế hoàn toàn nguồn thực phẩm từ chăn nuôi gia súc, gia cầm","Làm cạn kiệt toàn bộ nguồn nước ngọt phục vụ sinh hoạt"],"a":"Cung cấp thực phẩm giàu đạm cho con người và nguyên liệu cho xuất khẩu, công nghiệp chế biến","h":"Thuỷ sản là một trong những ngành kinh tế quan trọng của nước ta.","e":"Thuỷ sản cung cấp nguồn thực phẩm giàu đạm (tôm, cá...) cho con người, tạo nguyên liệu cho xuất khẩu và công nghiệp chế biến, đồng thời tạo việc làm và tăng thu nhập cho người dân vùng sông nước, ven biển.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để thu hoạch được toàn bộ số cá trong ao nuôi, người ta thường làm như thế nào?","o":["Dùng xung điện để làm cá nổi lên mặt nước rồi vớt","Thả thêm nhiều cá lớn vào ao để đuổi cá nhỏ lên bờ","Hạ dần mực nước, dùng lưới kéo thu cá nhiều lần, cuối cùng tháo cạn nước để bắt hết cá còn lại","Đợi đến khi ao tự cạn khô vào mùa nắng rồi nhặt cá"],"a":"Hạ dần mực nước, dùng lưới kéo thu cá nhiều lần, cuối cùng tháo cạn nước để bắt hết cá còn lại","h":"Đây là cách thu hoạch toàn bộ (thu hoạch triệt để) trong nuôi cá ao.","e":"Thu hoạch toàn bộ được thực hiện bằng cách rút bớt nước, kéo lưới thu cá nhiều lần rồi tháo cạn ao để bắt hết số cá còn lại. Sau khi thu hoạch cần xử lí ao (vét bùn, bón vôi, phơi đáy ao) để chuẩn bị cho vụ nuôi tiếp theo.","t":"cn-lop7","g":7,"l":"nhe-nhang"},{"p":"Bản vẽ kĩ thuật là tài liệu dùng để làm gì?","o":["Trang trí cho sản phẩm thêm đẹp","Quảng cáo sản phẩm tới người mua","Trình bày hình dạng, kích thước và yêu cầu kĩ thuật của sản phẩm để chế tạo và kiểm tra sản phẩm","Ghi lại địa chỉ của nhà máy sản xuất"],"a":"Trình bày hình dạng, kích thước và yêu cầu kĩ thuật của sản phẩm để chế tạo và kiểm tra sản phẩm","h":"Bản vẽ kĩ thuật được coi là ngôn ngữ chung trong kĩ thuật.","e":"Bản vẽ kĩ thuật trình bày đầy đủ hình dạng, kích thước và các yêu cầu kĩ thuật của sản phẩm theo quy tắc thống nhất, làm căn cứ để chế tạo và kiểm tra sản phẩm.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong phép chiếu vuông góc, các tia chiếu có đặc điểm gì?","o":["Song song với nhau và vuông góc với mặt phẳng hình chiếu","Hội tụ tại một điểm ở phía trước vật thể","Chiếu xiên góc tuỳ ý lên mặt phẳng hình chiếu","Luôn vuông góc với vật thể được chiếu"],"a":"Song song với nhau và vuông góc với mặt phẳng hình chiếu","h":"Tên gọi của phép chiếu gợi ý hướng của tia chiếu so với mặt phẳng hình chiếu.","e":"Phép chiếu vuông góc dùng các tia chiếu song song với nhau và vuông góc với mặt phẳng hình chiếu, cho hình chiếu đúng hình dạng, kích thước thật theo các chiều của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu đứng của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều rộng của vật thể","Chiều rộng và chiều cao của vật thể","Chỉ cho biết chiều cao của vật thể","Chiều dài và chiều cao của vật thể"],"a":"Chiều dài và chiều cao của vật thể","h":"Hình chiếu đứng là hình chiếu nhìn từ phía trước của vật thể.","e":"Hình chiếu đứng (nhìn từ phía trước) thể hiện chiều dài và chiều cao của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu bằng của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều cao của vật thể","Chiều dài và chiều rộng của vật thể","Chiều rộng và chiều cao của vật thể","Chỉ cho biết chiều rộng của vật thể"],"a":"Chiều dài và chiều rộng của vật thể","h":"Hình chiếu bằng là hình chiếu nhìn từ phía trên xuống.","e":"Hình chiếu bằng (nhìn từ trên xuống) thể hiện chiều dài và chiều rộng của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hình chiếu cạnh của vật thể cho biết những kích thước nào?","o":["Chiều dài và chiều cao của vật thể","Chiều rộng và chiều cao của vật thể","Chiều dài và chiều rộng của vật thể","Chỉ cho biết chiều cao của vật thể"],"a":"Chiều rộng và chiều cao của vật thể","h":"Hình chiếu cạnh là hình chiếu nhìn từ phía bên (trái) của vật thể.","e":"Hình chiếu cạnh (nhìn từ phía bên) thể hiện chiều rộng và chiều cao của vật thể.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Theo cách bố trí hình chiếu theo tiêu chuẩn Việt Nam, hình chiếu bằng được đặt ở vị trí nào so với hình chiếu đứng?","o":["Ở phía trên hình chiếu đứng","Ở phía bên phải hình chiếu đứng","Đặt tách rời, không liên quan vị trí với hình chiếu đứng","Ở phía dưới hình chiếu đứng"],"a":"Ở phía dưới hình chiếu đứng","h":"Vị trí các hình chiếu trên bản vẽ phải tuân theo quy tắc thống nhất để người đọc dễ đối chiếu.","e":"Theo phương pháp chiếu góc thứ nhất áp dụng ở Việt Nam: hình chiếu bằng đặt dưới hình chiếu đứng, hình chiếu cạnh đặt bên phải hình chiếu đứng.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Trên bản vẽ kĩ thuật, nét liền đậm được dùng để vẽ loại đường nào?","o":["Đường bao thấy của vật thể","Đường bao khuất của vật thể","Đường tâm và đường trục","Đường kích thước và đường gióng"],"a":"Đường bao thấy của vật thể","h":"Mỗi loại đường nét trên bản vẽ có quy định sử dụng riêng.","e":"Nét liền đậm dùng để vẽ đường bao thấy của vật thể; đường bao khuất vẽ bằng nét đứt, đường tâm và đường trục vẽ bằng nét gạch dài – chấm – mảnh.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nhóm vật liệu nào sau đây đều là vật liệu kim loại?","o":["Cao su, nhựa, đồng","Nhôm, gỗ, thuỷ tinh","Đồng, nhôm, thép","Thép, gốm, cao su"],"a":"Đồng, nhôm, thép","h":"Kim loại có tính dẫn điện, dẫn nhiệt và có ánh kim.","e":"Đồng, nhôm, thép đều là kim loại; cao su, nhựa, gỗ, thuỷ tinh, gốm là vật liệu phi kim loại.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Vật liệu nào sau đây là vật liệu phi kim loại?","o":["Gang","Đồng","Nhôm","Cao su"],"a":"Cao su","h":"Vật liệu phi kim loại thường không dẫn điện, cách nhiệt tốt.","e":"Cao su là vật liệu phi kim loại; gang, đồng, nhôm đều là kim loại (gang, đồng và nhôm là các kim loại/hợp kim thông dụng).","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Để đo kích thước của chi tiết cơ khí với độ chính xác cao, người ta thường dùng dụng cụ nào?","o":["Thước dây bằng vải","Thước cặp (thước kẹp)","Thước gỗ của học sinh","Ước lượng bằng mắt thường"],"a":"Thước cặp (thước kẹp)","h":"Thước cặp có du xích giúp đọc kích thước chính xác đến phần nhỏ của milimét.","e":"Thước cặp (thước kẹp) dùng để đo kích thước ngoài, kích thước trong và chiều sâu của chi tiết với độ chính xác cao, thường đạt 0,1 mm; 0,05 mm hoặc 0,02 mm.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi cưa và dũa kim loại, cần làm gì để đảm bảo an toàn?","o":["Dùng một tay giữ vật, một tay cầm cưa","Thổi mạnh cho phoi bay khỏi mặt bàn","Kẹp chặt vật gia công trên ê-tô và không dùng tay gạt phoi","Đứng càng sát lưỡi cưa càng tốt để nhìn rõ"],"a":"Kẹp chặt vật gia công trên ê-tô và không dùng tay gạt phoi","h":"Phoi kim loại sắc, dễ gây đứt tay và bắn vào mắt.","e":"Khi cưa, dũa phải kẹp chặt vật trên ê-tô, đeo kính bảo hộ; dùng bàn chải quét phoi, tuyệt đối không dùng tay gạt hoặc thổi phoi vì phoi sắc dễ gây thương tích.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi làm việc trong phân xưởng cơ khí, người lao động cần thực hiện điều nào sau đây?","o":["Mặc quần áo gọn gàng, đeo kính bảo hộ và tuân thủ nội quy an toàn lao động","Để tóc dài xoã tự do khi đứng gần máy đang chạy","Đùa nghịch, chạy nhảy trong phân xưởng","Đi dép lê để dễ di chuyển trong xưởng"],"a":"Mặc quần áo gọn gàng, đeo kính bảo hộ và tuân thủ nội quy an toàn lao động","h":"An toàn lao động là yêu cầu bắt buộc trong sản xuất cơ khí.","e":"Người lao động phải mặc trang phục gọn gàng, sử dụng đầy đủ dụng cụ bảo hộ (kính, găng tay phù hợp...) và tuân thủ nội quy an toàn để tránh tai nạn lao động.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Truyền động đai truyền được chuyển động là nhờ vào đâu?","o":["Lực ma sát giữa dây đai và bánh đai","Các răng của hai bánh ăn khớp với nhau","Lực hút của nam châm giữa hai bánh","Áp lực của dầu bôi trơn"],"a":"Lực ma sát giữa dây đai và bánh đai","h":"Dây đai ôm sát và ép lên bề mặt bánh đai khi làm việc.","e":"Trong truyền động đai, chuyển động được truyền nhờ lực ma sát giữa dây đai và bánh đai; bánh dẫn quay kéo dây đai chuyển động làm bánh bị dẫn quay theo.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong truyền động bánh răng, chuyển động được truyền đi bằng cách nào?","o":["Một dây đai nối hai bánh răng lại","Hai mặt bánh nhẵn ép chặt vào nhau","Các răng của hai bánh răng ăn khớp trực tiếp với nhau","Một sợi xích nối hai bánh răng"],"a":"Các răng của hai bánh răng ăn khớp trực tiếp với nhau","h":"Truyền động bánh răng thường dùng khi cần tỉ số truyền chính xác.","e":"Truyền động bánh răng truyền chuyển động nhờ các răng của bánh dẫn và bánh bị dẫn ăn khớp với nhau, cho tỉ số truyền chính xác, không bị trượt.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cơ cấu tay quay – con trượt có tác dụng biến đổi chuyển động như thế nào?","o":["Biến chuyển động tịnh tiến thành chuyển động quay","Biến chuyển động quay thành chuyển động tịnh tiến qua lại","Biến chuyển động quay chậm thành chuyển động quay nhanh hơn","Giữ nguyên chuyển động quay, không biến đổi"],"a":"Biến chuyển động quay thành chuyển động tịnh tiến qua lại","h":"Cơ cấu này có trong động cơ đốt trong và máy nén khí.","e":"Cơ cấu tay quay – con trượt biến chuyển động quay của tay quay thành chuyển động tịnh tiến qua lại của con trượt (ứng dụng trong máy khâu đạp chân, động cơ...).","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Một mạch điện trong gia đình cơ bản gồm những thành phần chính nào?","o":["Chỉ gồm bóng đèn và dây dẫn","Chỉ gồm nguồn điện và công tắc","Gồm pin, chuông và đèn pin","Nguồn điện, dây dẫn, thiết bị đóng – cắt và bảo vệ, thiết bị tiêu thụ điện"],"a":"Nguồn điện, dây dẫn, thiết bị đóng – cắt và bảo vệ, thiết bị tiêu thụ điện","h":"Mạch điện phải là một vòng kín gồm đủ các phần tử cơ bản.","e":"Mạch điện gồm: nguồn điện, dây dẫn, thiết bị đóng – cắt (công tắc, cầu dao), thiết bị bảo vệ (cầu chì, át-tô-mát) và thiết bị tiêu thụ điện (phụ tải).","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cầu chì có tác dụng gì trong mạch điện gia đình?","o":["Làm tăng điện áp cho các thiết bị điện","Giúp tiết kiệm điện năng tiêu thụ","Tự động ngắt mạch điện khi xảy ra ngắn mạch hoặc quá tải để bảo vệ mạch điện","Thay thế hoàn toàn cho công tắc điện"],"a":"Tự động ngắt mạch điện khi xảy ra ngắn mạch hoặc quá tải để bảo vệ mạch điện","h":"Cầu chì là thiết bị bảo vệ, không phải thiết bị đóng – cắt thông thường.","e":"Khi dòng điện tăng quá mức cho phép (ngắn mạch, quá tải), dây chì trong cầu chì nóng chảy và đứt, tự động ngắt mạch, bảo vệ dây dẫn và thiết bị điện khỏi cháy hỏng.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi dòng điện trong mạch vượt quá giá trị cho phép, cầu chì bảo vệ mạch điện bằng cách nào?","o":["Dây chì phát sáng để báo hiệu cho người dùng","Dây chì giãn dài ra làm hở tiếp điểm","Vỏ cầu chì tự vỡ để thoát nhiệt","Dây chì bị dòng điện lớn làm nóng chảy và đứt, ngắt mạch điện"],"a":"Dây chì bị dòng điện lớn làm nóng chảy và đứt, ngắt mạch điện","h":"Dây chì làm bằng kim loại dễ nóng chảy, mắc nối tiếp trong mạch điện.","e":"Dây chì có nhiệt độ nóng chảy thấp; khi dòng điện vượt quá định mức, dây chì nóng chảy và đứt ra, ngắt mạch điện, bảo vệ toàn bộ mạch phía sau cầu chì.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Át-tô-mát (cầu dao tự động) khác cầu chì ở điểm nào sau đây?","o":["Sau khi tự ngắt do sự cố, có thể đóng lại để sử dụng tiếp mà không phải thay thế bộ phận","Không có khả năng ngắt mạch khi quá tải","Chỉ sử dụng được cho mạch điện một chiều","Không có tác dụng bảo vệ mạch điện"],"a":"Sau khi tự ngắt do sự cố, có thể đóng lại để sử dụng tiếp mà không phải thay thế bộ phận","h":"Hãy liên hệ với cầu dao tự động thường lắp ở đầu nguồn điện trong nhà.","e":"Át-tô-mát tự động ngắt mạch khi quá tải hoặc ngắn mạch; sau khi khắc phục sự cố chỉ cần gạt cần đóng lại là dùng tiếp, tiện lợi hơn cầu chì phải thay dây chì mới.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG an toàn khi sử dụng điện?","o":["Rút phích cắm khi không sử dụng thiết bị điện","Dùng tay còn ướt để cắm phích điện vào ổ cắm","Kiểm tra và thay dây điện đã bị hở lõi","Ngắt cầu dao trước khi sửa chữa thiết bị điện"],"a":"Dùng tay còn ướt để cắm phích điện vào ổ cắm","h":"Nước là chất dẫn điện, tay ướt làm điện trở của cơ thể giảm mạnh.","e":"Tay ướt khi tiếp xúc với thiết bị điện rất dễ gây điện giật nguy hiểm; các việc còn lại đều là thói quen sử dụng điện an toàn.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Các thiết bị điện có vỏ bằng kim loại như tủ lạnh, máy giặt cần được nối đất nhằm mục đích gì?","o":["Giúp thiết bị tiêu thụ ít điện năng hơn","Tránh cho người sử dụng bị điện giật khi thiết bị bị rò điện ra vỏ","Làm cho thiết bị hoạt động mạnh hơn","Kéo dài tuổi thọ của động cơ thiết bị"],"a":"Tránh cho người sử dụng bị điện giật khi thiết bị bị rò điện ra vỏ","h":"Khi thiết bị rò điện, dòng điện rò cần có đường thoát xuống đất thay vì qua cơ thể người.","e":"Nối đất giúp dòng điện rò từ vỏ kim loại truyền xuống đất, bảo vệ người sử dụng không bị điện giật khi chạm vào thiết bị bị rò điện.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi phát hiện dây điện bị đứt và rơi xuống đất, em cần làm gì?","o":["Đứng tránh xa, không chạm vào dây và báo ngay cho người lớn hoặc đơn vị điện lực","Cầm lấy dây để nối lại ngay","Dùng cây gậy còn ướt đẩy dây sang một bên","Đổ nước lên đoạn dây cho an toàn"],"a":"Đứng tránh xa, không chạm vào dây và báo ngay cho người lớn hoặc đơn vị điện lực","h":"Dây điện đứt rơi xuống đất vẫn có thể đang mang điện, cực kì nguy hiểm.","e":"Dây điện đứt có thể vẫn còn điện; phải đứng xa, cảnh báo mọi người không lại gần và báo ngay cho người lớn hoặc cơ quan điện lực đến xử lí.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khổ giấy A4 dùng trong bản vẽ kĩ thuật có kích thước là bao nhiêu?","o":["297 mm × 210 mm","420 mm × 297 mm","210 mm × 148 mm","594 mm × 420 mm"],"a":"297 mm × 210 mm","h":"A4 là khổ giấy nhỏ nhất trong dãy khổ giấy chính A0–A4, cũng là khổ giấy in thông dụng hằng ngày.","e":"Theo tiêu chuẩn, các khổ giấy chính gồm A0 (1189 × 841 mm), A1, A2, A3 và A4; khổ A4 có kích thước 297 mm × 210 mm.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trên bản vẽ kĩ thuật có tỉ lệ 1 : 2, một đoạn thẳng được vẽ dài 30 mm. Kích thước thật của chi tiết là bao nhiêu?","o":["15 mm","30 mm","60 mm","90 mm"],"a":"60 mm","h":"Tỉ lệ 1 : 2 là tỉ lệ thu nhỏ: kích thước trên bản vẽ bằng một nửa kích thước thật.","e":"Với tỉ lệ thu nhỏ 1 : 2, kích thước thật gấp đôi kích thước vẽ: 30 × 2 = 60 mm.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Khung tên của bản vẽ kĩ thuật thường được đặt ở vị trí nào?","o":["Ở góc dưới bên phải của bản vẽ","Ở góc trên bên trái của bản vẽ","Ở chính giữa bản vẽ","Ở góc dưới bên trái của bản vẽ"],"a":"Ở góc dưới bên phải của bản vẽ","h":"Khung tên ghi tên gọi chi tiết, tỉ lệ, người vẽ, người kiểm tra… và luôn nằm ở một góc cố định.","e":"Theo tiêu chuẩn trình bày bản vẽ, khung tên được đặt ở góc dưới bên phải của tờ giấy vẽ để thống nhất cách đọc và quản lí bản vẽ.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một vật thể hình trụ được đặt thẳng đứng. Hình chiếu bằng của vật thể đó là hình gì?","o":["Hình chữ nhật","Hình tròn","Hình tam giác","Hình vuông"],"a":"Hình tròn","h":"Hình chiếu bằng là hình nhìn từ trên xuống theo phương vuông góc với mặt phẳng nằm ngang.","e":"Nhìn hình trụ đứng từ trên xuống, ta thấy mặt đáy là hình tròn nên hình chiếu bằng là hình tròn; hình chiếu đứng và hình chiếu cạnh của nó mới là hình chữ nhật.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bản vẽ chi tiết gồm những nội dung chính nào sau đây?","o":["Hình biểu diễn, kích thước, yêu cầu kĩ thuật và khung tên","Hình biểu diễn, kích thước, bảng kê và khung tên","Chỉ gồm hình biểu diễn của chi tiết","Mặt bằng, mặt đứng và mặt cắt của chi tiết"],"a":"Hình biểu diễn, kích thước, yêu cầu kĩ thuật và khung tên","h":"Bản vẽ chi tiết dùng để chế tạo và kiểm tra một chi tiết nên phải ghi cả yêu cầu kĩ thuật.","e":"Bản vẽ chi tiết gồm: hình biểu diễn, các kích thước, các yêu cầu kĩ thuật (độ nhám, dung sai…) và khung tên; nó là căn cứ để chế tạo và kiểm tra chi tiết.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bản vẽ lắp gồm những nội dung chính nào sau đây?","o":["Hình biểu diễn, kích thước, bảng kê và khung tên","Hình biểu diễn, kích thước, yêu cầu kĩ thuật và khung tên","Chỉ gồm bảng kê các chi tiết","Mặt bằng và mặt đứng của sản phẩm"],"a":"Hình biểu diễn, kích thước, bảng kê và khung tên","h":"Khác với bản vẽ chi tiết, bản vẽ lắp cần bảng kê để liệt kê tên gọi, số lượng các chi tiết cấu thành sản phẩm.","e":"Bản vẽ lắp thể hiện hình dạng và vị trí tương quan giữa các chi tiết của sản phẩm, gồm hình biểu diễn, kích thước lắp, bảng kê chi tiết và khung tên.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong bản vẽ nhà, mặt bằng là hình biểu diễn cho biết điều gì?","o":["Hình dạng bên ngoài của ngôi nhà khi nhìn từ phía trước","Cách bố trí các phòng, cửa ra vào, cửa sổ của ngôi nhà","Kết cấu móng và mái của ngôi nhà","Chiều cao của từng tầng nhà"],"a":"Cách bố trí các phòng, cửa ra vào, cửa sổ của ngôi nhà","h":"Mặt bằng tương ứng với hình chiếu bằng của ngôi nhà.","e":"Mặt bằng là hình cắt bằng của ngôi nhà, cho thấy hình dạng, kích thước và cách bố trí các phòng, cửa đi, cửa sổ; còn mặt đứng cho hình dạng bên ngoài và mặt cắt cho kết cấu bên trong.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nhóm tính chất nào sau đây thuộc tính chất cơ học của vật liệu?","o":["Tính dẫn điện, tính dẫn nhiệt","Khối lượng riêng, nhiệt độ nóng chảy","Độ bền, độ cứng, độ dẻo","Khả năng chống ăn mòn, chịu axit"],"a":"Độ bền, độ cứng, độ dẻo","h":"Tính chất cơ học thể hiện qua khả năng chịu tác dụng của lực bên ngoài.","e":"Tính chất cơ học của vật liệu gồm độ bền, độ cứng, độ dẻo, độ dai…; tính dẫn điện, dẫn nhiệt và khối lượng riêng thuộc tính chất lí học, còn chống ăn mòn thuộc tính chất hoá học.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Gang và thép được xếp vào nhóm kim loại đen vì lí do nào?","o":["Vì chúng có màu đen","Vì thành phần chủ yếu là sắt và cacbon","Vì chúng không dẫn điện","Vì chúng nặng hơn mọi kim loại khác"],"a":"Vì thành phần chủ yếu là sắt và cacbon","h":"Tên gọi kim loại đen gắn với thành phần hoá học chứ không phải màu sắc bề ngoài.","e":"Kim loại đen là kim loại có thành phần chủ yếu là sắt và cacbon, điển hình là gang và thép; đồng, nhôm, kẽm… thuộc nhóm kim loại màu.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong bộ truyền động quay, tỉ số truyền i được xác định như thế nào?","o":["i = tốc độ quay của trục bị dẫn chia cho tốc độ quay của trục dẫn","i = tốc độ quay của trục dẫn chia cho tốc độ quay của trục bị dẫn","i = tổng tốc độ quay của hai trục","i = hiệu tốc độ quay của hai trục"],"a":"i = tốc độ quay của trục dẫn chia cho tốc độ quay của trục bị dẫn","h":"Tỉ số truyền cho biết trục bị dẫn quay nhanh hay chậm hơn trục dẫn bao nhiêu lần.","e":"Tỉ số truyền i = n1/n2, trong đó n1 là tốc độ quay của trục (bánh) dẫn, n2 là tốc độ quay của trục (bánh) bị dẫn; i > 1 thì trục bị dẫn quay chậm hơn trục dẫn.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bánh răng dẫn có 40 răng, quay với tốc độ 600 vòng/phút. Bánh răng bị dẫn có 20 răng. Bánh răng bị dẫn quay với tốc độ bao nhiêu?","o":["300 vòng/phút","600 vòng/phút","1200 vòng/phút","2400 vòng/phút"],"a":"1200 vòng/phút","h":"Tốc độ quay tỉ lệ nghịch với số răng: bánh bị dẫn ít răng hơn nên quay nhanh hơn.","e":"Tỉ số truyền i = Z1/Z2 = 40/20 = 2, nên n2 = n1 × i… cụ thể n2 = 600 × 40/20 = 1200 vòng/phút.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Thước cặp được dùng để đo những loại kích thước nào của chi tiết?","o":["Chỉ đo được chiều dài của vật thẳng","Đo kích thước ngoài, kích thước trong (lỗ) và chiều sâu","Đo góc và độ nghiêng của chi tiết","Đo độ nhám bề mặt chi tiết"],"a":"Đo kích thước ngoài, kích thước trong (lỗ) và chiều sâu","h":"Thước cặp có mỏ đo ngoài, mỏ đo trong và một thanh đo sâu ở đuôi thước.","e":"Nhờ hai cặp mỏ đo và thanh đo sâu, thước cặp đo được kích thước ngoài, đường kính trong của lỗ và chiều sâu của lỗ/rãnh với độ chính xác cao hơn thước lá.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi giũa kim loại, cách làm nào sau đây là an toàn và đúng quy định?","o":["Thổi mạnh cho phoi kim loại bay đi","Dùng giũa đã bị gãy hoặc không có cán","Dùng giũa có cán chắc chắn và quét phoi bằng bàn chải","Dùng tay gạt phoi trên mặt giũa"],"a":"Dùng giũa có cán chắc chắn và quét phoi bằng bàn chải","h":"Phoi kim loại sắc và nóng; cán giũa hỏng có thể làm chuôi giũa đâm vào tay khi giũa.","e":"Khi giũa phải dùng giũa có cán nguyên vẹn, lắp chắc; phoi kim loại được quét bằng bàn chải, tuyệt đối không thổi bằng miệng hay gạt bằng tay vì dễ gây thương tích và phoi bay vào mắt.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nhóm nghề nào sau đây thuộc lĩnh vực cơ khí chế tạo?","o":["Tiện, phay, hàn, nguội","May, thêu, dệt vải","Nấu ăn, pha chế đồ uống","Trồng trọt, chăn nuôi"],"a":"Tiện, phay, hàn, nguội","h":"Đây là các nghề trực tiếp gia công, chế tạo chi tiết và sản phẩm bằng kim loại.","e":"Tiện, phay, hàn, nguội (cùng với đúc, rèn, gò…) là các nghề phổ biến trong lĩnh vực cơ khí, gắn với gia công và lắp ráp sản phẩm cơ khí.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Người lao động trong lĩnh vực cơ khí cần đáp ứng yêu cầu nào sau đây?","o":["Chỉ cần có sức khoẻ, không cần học nghề","Có sức khoẻ tốt, được đào tạo nghề, khéo léo, cẩn thận và tuân thủ quy định an toàn lao động","Chỉ cần làm việc nhanh, không cần cẩn thận","Không cần tuân thủ quy định an toàn khi đã quen việc"],"a":"Có sức khoẻ tốt, được đào tạo nghề, khéo léo, cẩn thận và tuân thủ quy định an toàn lao động","h":"Công việc cơ khí gắn với máy móc và dụng cụ sắc, nặng nên yêu cầu cả tay nghề lẫn ý thức an toàn.","e":"Người thợ cơ khí cần có sức khoẻ, trình độ chuyên môn (qua đào tạo), tính khéo léo, cẩn thận, kiên trì và đặc biệt phải tuân thủ các quy định về an toàn lao động.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nguyên nhân nào sau đây là nguyên nhân trực tiếp thường gây tai nạn điện?","o":["Sử dụng thiết bị điện đúng công suất định mức","Chạm vào dây dẫn điện bị hở cách điện hoặc phần kim loại có điện","Thay bóng đèn sau khi đã ngắt điện","Dùng phích cắm và tay khô ráo khi cắm điện"],"a":"Chạm vào dây dẫn điện bị hở cách điện hoặc phần kim loại có điện","h":"Tai nạn điện xảy ra khi cơ thể người trở thành một phần của mạch điện.","e":"Nguyên nhân trực tiếp gây tai nạn điện là tiếp xúc trực tiếp với vật mang điện (dây hở cách điện, ổ cắm hỏng…) hoặc đến quá gần nguồn điện cao áp; các việc làm còn lại đều là biện pháp an toàn.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Mức độ nguy hiểm của dòng điện đối với cơ thể người phụ thuộc chủ yếu vào những yếu tố nào?","o":["Màu sắc của dây dẫn điện","Công suất của bóng đèn trong mạch","Cường độ dòng điện qua người và thời gian dòng điện tác dụng lên cơ thể","Độ dài của dây dẫn điện"],"a":"Cường độ dòng điện qua người và thời gian dòng điện tác dụng lên cơ thể","h":"Cùng một nguồn điện, dòng qua người càng lớn và càng lâu thì tổn thương càng nặng.","e":"Mức độ tác hại của dòng điện lên cơ thể phụ thuộc chủ yếu vào cường độ dòng điện đi qua người và thời gian tác dụng (ngoài ra còn tùy đường đi của dòng điện qua cơ thể, ví dụ qua tim là nguy hiểm nhất).","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Trước khi sửa chữa thiết bị điện trong nhà, việc làm đầu tiên và quan trọng nhất là gì?","o":["Tháo vỏ thiết bị ra ngay để kiểm tra","Rửa tay thật sạch rồi mới sửa","Ngắt nguồn điện ở cầu dao/át-tô-mát và dùng bút thử điện kiểm tra lại","Nhờ người khác đứng cạnh quan sát"],"a":"Ngắt nguồn điện ở cầu dao/át-tô-mát và dùng bút thử điện kiểm tra lại","h":"Nguyên tắc an toàn khi sửa chữa điện là phải bảo đảm thiết bị hoàn toàn không còn điện.","e":"Khi sửa chữa điện phải ngắt nguồn (cắt cầu dao hoặc át-tô-mát), kiểm tra lại bằng bút thử điện, sử dụng dụng cụ có tay cầm cách điện và không làm việc khi tay hoặc nền nhà ẩm ướt.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi phát hiện có người bị điện giật, việc làm đầu tiên cần thực hiện là gì?","o":["Lao vào kéo nạn nhân ra bằng tay trần","Đổ nước lên người nạn nhân","Nhanh chóng ngắt nguồn điện hoặc dùng vật khô cách điện (gậy gỗ, nhựa) tách nạn nhân khỏi nguồn điện","Hô hấp nhân tạo ngay trong khi nạn nhân còn dính với nguồn điện"],"a":"Nhanh chóng ngắt nguồn điện hoặc dùng vật khô cách điện (gậy gỗ, nhựa) tách nạn nhân khỏi nguồn điện","h":"Phải bảo đảm an toàn cho người cứu trước, nếu không sẽ có thêm nạn nhân.","e":"Bước đầu tiên khi cứu người bị điện giật là cắt nguồn điện hoặc dùng vật khô không dẫn điện tách nạn nhân ra; sau đó mới kiểm tra hô hấp, tiến hành hô hấp nhân tạo/ép tim nếu cần và gọi cấp cứu 115.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong mạch điện, thiết bị đóng – cắt có nhiệm vụ gì?","o":["Cung cấp năng lượng điện cho mạch","Biến đổi điện năng thành quang năng, nhiệt năng","Đóng hoặc ngắt dòng điện trong mạch khi cần thiết","Dẫn điện từ nguồn đến nơi tiêu thụ"],"a":"Đóng hoặc ngắt dòng điện trong mạch khi cần thiết","h":"Công tắc, cầu dao, át-tô-mát đều thuộc nhóm thiết bị đóng – cắt và bảo vệ mạch điện.","e":"Thiết bị đóng – cắt (công tắc, cầu dao…) dùng để đóng hoặc ngắt dòng điện trong mạch; nguồn điện cung cấp năng lượng, dây dẫn truyền điện và tải tiêu thụ điện năng.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Sơ đồ mạch điện là hình vẽ thể hiện nội dung gì?","o":["Hình dạng thật và màu sắc của các thiết bị điện","Cách nối các phần tử trong mạch điện bằng các kí hiệu quy ước","Giá tiền của các thiết bị trong mạch","Kích thước thật của dây dẫn điện"],"a":"Cách nối các phần tử trong mạch điện bằng các kí hiệu quy ước","h":"Nhờ kí hiệu quy ước thống nhất, ai cũng đọc và lắp được mạch điện theo sơ đồ.","e":"Sơ đồ mạch điện dùng các kí hiệu quy ước để thể hiện các phần tử (nguồn, tải, thiết bị đóng cắt, dây dẫn) và cách nối chúng, làm căn cứ để lắp đặt và sửa chữa mạch điện.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cảm biến là thiết bị dùng để làm gì?","o":["Cung cấp nguồn điện cho mạch","Lưu trữ điện năng như pin","Biến đổi các đại lượng vật lí như ánh sáng, nhiệt độ, độ ẩm thành tín hiệu điện","Khuếch đại âm thanh trong mạch điện"],"a":"Biến đổi các đại lượng vật lí như ánh sáng, nhiệt độ, độ ẩm thành tín hiệu điện","h":"Cảm biến được coi là 'giác quan' của các hệ thống điều khiển tự động.","e":"Cảm biến chuyển đổi các đại lượng cần đo (ánh sáng, nhiệt độ, độ ẩm, khoảng cách…) thành tín hiệu điện để mạch điều khiển xử lí và ra lệnh cho thiết bị hoạt động.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cảm biến ánh sáng hoạt động dựa trên sự thay đổi của đại lượng nào?","o":["Nhiệt độ của môi trường","Độ ẩm của không khí","Cường độ ánh sáng chiếu vào cảm biến","Áp suất không khí"],"a":"Cường độ ánh sáng chiếu vào cảm biến","h":"Trời càng tối, tín hiệu từ cảm biến ánh sáng càng thay đổi rõ so với ban ngày.","e":"Cảm biến ánh sáng (quang trở, quang điện) thay đổi đặc tính điện theo cường độ ánh sáng chiếu vào; nhờ đó mạch điều khiển phân biệt được trời sáng hay trời tối.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Mô đun cảm biến độ ẩm đất thường được ứng dụng vào việc nào sau đây?","o":["Tự động bật đèn đường khi trời tối","Tự động tưới cây khi đất khô","Báo cháy khi có khói trong nhà","Tự động mở cửa khi có người đến gần"],"a":"Tự động tưới cây khi đất khô","h":"Mỗi loại cảm biến đo một đại lượng riêng và phục vụ một ứng dụng tương ứng.","e":"Cảm biến độ ẩm đất đo độ ẩm của đất; khi đất khô dưới ngưỡng đặt trước, mô đun điều khiển sẽ bật máy bơm tưới cây — ứng dụng phổ biến trong nông nghiệp thông minh.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong mạch đèn đường tự động dùng cảm biến ánh sáng, đèn tự sáng khi trời tối theo nguyên lí nào?","o":["Đèn tự phát sáng nhờ nhiệt độ ban đêm thấp","Cảm biến nhận biết trời tối và gửi tín hiệu về mô đun điều khiển, mô đun đóng rơ-le cấp điện cho đèn","Nhờ người bảo vệ bật công tắc mỗi tối","Nhờ pin trong đèn tự nạp đầy vào ban ngày"],"a":"Cảm biến nhận biết trời tối và gửi tín hiệu về mô đun điều khiển, mô đun đóng rơ-le cấp điện cho đèn","h":"Chuỗi hoạt động gồm: cảm biến đo → mô đun xử lí tín hiệu → rơ-le đóng mạch cấp điện cho đèn.","e":"Khi trời tối, cảm biến ánh sáng gửi tín hiệu thay đổi về mô đun cảm biến/điều khiển; mô đun này tác động lên rơ-le để đóng mạch, cấp điện cho đèn sáng, và tự tắt khi trời sáng.","t":"cn-lop8","g":8,"l":"thu-thach"},{"p":"Trong mạch điện điều khiển sử dụng mô đun cảm biến, rơ-le (relay) có vai trò gì?","o":["Đo nhiệt độ và độ ẩm của môi trường","Cung cấp nguồn điện cho toàn bộ mạch","Đóng – cắt mạch điện của thiết bị theo tín hiệu điều khiển từ mô đun cảm biến","Hiển thị các thông số đo được"],"a":"Đóng – cắt mạch điện của thiết bị theo tín hiệu điều khiển từ mô đun cảm biến","h":"Tín hiệu từ cảm biến rất nhỏ, không thể trực tiếp vận hành các thiết bị công suất lớn như đèn, quạt, máy bơm.","e":"Rơ-le là thiết bị đóng – cắt bằng điện: khi nhận tín hiệu điều khiển từ mô đun cảm biến, rơ-le đóng hoặc ngắt mạch cấp điện cho tải (đèn, quạt, máy bơm…), giúp điều khiển tự động các thiết bị.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nghề nào sau đây thuộc lĩnh vực kĩ thuật điện?","o":["Thợ tiện, thợ phay cơ khí","Thợ lắp đặt và sửa chữa mạng điện dân dụng, điện công nghiệp","Thợ may công nghiệp","Thợ xây dựng cầu đường"],"a":"Thợ lắp đặt và sửa chữa mạng điện dân dụng, điện công nghiệp","h":"Người làm nghề điện phải được đào tạo chuyên môn và đặc biệt coi trọng an toàn điện.","e":"Lĩnh vực kĩ thuật điện gồm các nghề như lắp đặt, vận hành, sửa chữa mạng điện dân dụng và công nghiệp; người thợ điện cần có kiến thức về điện, khéo léo, cẩn thận và tuân thủ nghiêm ngặt quy tắc an toàn điện.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Thiết kế kĩ thuật là hoạt động như thế nào?","o":["Sao chép lại nguyên văn sản phẩm đã có sẵn","Hoạt động sáng tạo nhằm tạo ra sản phẩm mới hoặc cải tiến sản phẩm để đáp ứng nhu cầu thực tế","Trang trí cho sản phẩm đẹp hơn trước khi bán","Quảng cáo sản phẩm tới người tiêu dùng"],"a":"Hoạt động sáng tạo nhằm tạo ra sản phẩm mới hoặc cải tiến sản phẩm để đáp ứng nhu cầu thực tế","h":"Mọi sản phẩm kĩ thuật quanh ta đều bắt đầu từ một quá trình thiết kế.","e":"Thiết kế kĩ thuật là quá trình sáng tạo, tạo ra bản vẽ, mô hình và hồ sơ kĩ thuật của sản phẩm; nó có vai trò tạo ra sản phẩm mới, cải tiến sản phẩm hiện có, nâng cao chất lượng và giảm giá thành.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bước đầu tiên trong quy trình thiết kế kĩ thuật là gì?","o":["Chế tạo nguyên mẫu của sản phẩm","Lập hồ sơ kĩ thuật cho sản phẩm","Thử nghiệm và đánh giá sản phẩm","Xác định vấn đề (nhu cầu) cần giải quyết"],"a":"Xác định vấn đề (nhu cầu) cần giải quyết","h":"Muốn thiết kế đúng, trước hết phải biết rõ mình cần giải quyết nhu cầu gì, cho ai.","e":"Quy trình thiết kế kĩ thuật gồm các bước: xác định vấn đề → đề xuất giải pháp → lựa chọn giải pháp → tạo nguyên mẫu → thử nghiệm, đánh giá → lập hồ sơ kĩ thuật; bước đầu tiên luôn là xác định vấn đề cần giải quyết.","t":"cn-lop8","g":8,"l":"nhe-nhang"},{"p":"Áptômát (cầu dao tự động) trong mạng điện gia đình có chức năng chính là gì?","o":["Đóng và cắt mạch điện bằng tay khi cần dùng điện","Tự động ngắt mạch khi có sự cố quá tải hoặc ngắn mạch","Tăng điện áp cho các thiết bị điện trong nhà","Đo lượng điện năng tiêu thụ của gia đình"],"a":"Tự động ngắt mạch khi có sự cố quá tải hoặc ngắn mạch","h":"Đây là thiết bị bảo vệ, hoạt động không cần con người tác động.","e":"Áptômát vừa đóng vai trò thiết bị đóng cắt, vừa tự động ngắt mạch khi dòng điện vượt quá mức cho phép hoặc xảy ra ngắn mạch, giúp bảo vệ mạng điện và thiết bị.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dây dẫn điện trong nhà thường được làm bằng đồng vì lí do nào sau đây?","o":["Đồng dẫn điện tốt và tương đối bền","Đồng là kim loại nhẹ nhất","Đồng không bao giờ bị oxi hoá","Đồng rẻ hơn mọi kim loại khác"],"a":"Đồng dẫn điện tốt và tương đối bền","h":"Hãy nhớ tính chất vật lí quan trọng nhất của vật liệu làm dây dẫn.","e":"Đồng có điện trở suất nhỏ, dẫn điện tốt, độ bền cơ học khá cao nên được dùng phổ biến làm lõi dây dẫn điện.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi cần sửa chữa hoặc thay thế một thiết bị điện trong nhà, việc đầu tiên phải làm để đảm bảo an toàn là gì?","o":["Dùng bút thử điện kiểm tra vỏ thiết bị","Đeo găng tay cao su rồi thao tác ngay","Ngắt nguồn điện bằng áptômát hoặc cầu dao tổng","Rút hết phích cắm của các thiết bị khác trong nhà"],"a":"Ngắt nguồn điện bằng áptômát hoặc cầu dao tổng","h":"Nguyên tắc an toàn điện đầu tiên: cắt nguồn trước khi chạm vào mạch điện.","e":"Trước khi sửa chữa, lắp đặt thiết bị điện phải ngắt nguồn điện ở cầu dao/áptômát tổng và kiểm tra lại bằng bút thử điện để tránh bị điện giật.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Sơ đồ lắp đặt mạng điện trong nhà thể hiện nội dung gì?","o":["Màu sắc và kiểu dáng của các thiết bị điện","Giá thành của toàn bộ mạng điện","Cách trang trí dây điện cho đẹp nhà","Vị trí lắp đặt và cách nối dây giữa các phần tử của mạng điện"],"a":"Vị trí lắp đặt và cách nối dây giữa các phần tử của mạng điện","h":"Sơ đồ này là bản vẽ kĩ thuật dùng để thi công lắp đặt.","e":"Sơ đồ lắp đặt biểu diễn vị trí thực tế của các thiết bị (cầu dao, công tắc, ổ cắm, bóng đèn...) và đường đi của dây dẫn để thợ điện thi công đúng thiết kế.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cầu chì trong mạch điện có tác dụng gì?","o":["Bảo vệ mạch điện, dây chì tự chảy và ngắt mạch khi dòng điện tăng quá mức","Làm cho bóng đèn sáng hơn bình thường","Biến đổi dòng điện xoay chiều thành một chiều","Đo cường độ dòng điện trong mạch"],"a":"Bảo vệ mạch điện, dây chì tự chảy và ngắt mạch khi dòng điện tăng quá mức","h":"Khi quá tải, bộ phận nào trong cầu chì sẽ bị nóng chảy trước?","e":"Dây chì trong cầu chì có nhiệt độ nóng chảy thấp; khi dòng điện vượt quá giá trị cho phép, dây chì nóng chảy và cắt mạch, bảo vệ các thiết bị phía sau.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Việc làm nào sau đây KHÔNG an toàn khi sử dụng điện trong gia đình?","o":["Không cắm chung quá nhiều thiết bị vào một ổ cắm","Dùng tay ướt để bật công tắc và cắm phích điện","Thay bóng đèn khi đã ngắt điện","Để dây điện tránh xa nguồn nhiệt cao"],"a":"Dùng tay ướt để bật công tắc và cắm phích điện","h":"Nước làm tăng khả năng dẫn điện của cơ thể người.","e":"Tay ướt làm điện trở của da giảm mạnh, dòng điện dễ truyền qua cơ thể gây điện giật nguy hiểm, vì vậy tuyệt đối không thao tác với thiết bị điện khi tay ướt.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Các thiết bị điện có vỏ bằng kim loại (như tủ lạnh, máy giặt) thường được nối đất nhằm mục đích gì?","o":["Giúp thiết bị chạy êm và nhanh hơn","Tiết kiệm điện năng khi vận hành","Tăng tuổi thọ của động cơ điện","Đưa dòng điện rò rỉ xuống đất, tránh nguy hiểm cho người sử dụng"],"a":"Đưa dòng điện rò rỉ xuống đất, tránh nguy hiểm cho người sử dụng","h":"Hãy nghĩ đến trường hợp vỏ kim loại bị rò điện.","e":"Khi có sự cố rò điện ra vỏ kim loại, dây nối đất dẫn dòng điện xuống đất thay vì truyền qua cơ thể người chạm vào, giúp tránh bị điện giật.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi chọn giống cây ăn quả để trồng, yêu cầu quan trọng nhất là gì?","o":["Giống cây phải là giống đắt tiền nhất","Giống cây phải có quả to nhất thị trường","Giống cây phải phù hợp với điều kiện khí hậu, đất đai của địa phương","Giống cây phải là giống mới nhập từ nước ngoài"],"a":"Giống cây phải phù hợp với điều kiện khí hậu, đất đai của địa phương","h":"Cây chỉ sinh trưởng tốt khi điều kiện ngoại cảnh thích hợp với đặc tính của giống.","e":"Mỗi giống cây ăn quả thích nghi với một điều kiện khí hậu, đất đai nhất định; chọn giống phù hợp địa phương giúp cây sinh trưởng tốt, ít sâu bệnh và cho năng suất cao.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi trồng cây ăn quả, người ta thường bón phân hữu cơ hoai mục xuống hố trước khi đặt cây (bón lót) nhằm mục đích gì?","o":["Cung cấp chất dinh dưỡng cho cây trong giai đoạn đầu sau khi trồng","Làm cho hố trồng sâu hơn","Xua đuổi sâu bọ trong đất","Giữ cho bầu đất không bị vỡ"],"a":"Cung cấp chất dinh dưỡng cho cây trong giai đoạn đầu sau khi trồng","h":"Phân hữu cơ phân huỷ chậm nên cần được chôn sẵn dưới hố.","e":"Bón lót bằng phân hữu cơ hoai mục trộn với đất ở đáy hố giúp cung cấp dinh dưỡng từ từ cho bộ rễ mới phát triển, giúp cây bén rễ và hồi xanh nhanh.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đối với cây ăn quả, bón phân thúc thường được thực hiện vào những thời điểm nào?","o":["Chỉ bón một lần duy nhất khi mới trồng","Bón vào lúc cây đang bị sâu bệnh nặng","Bón trước khi cây ra hoa và trong giai đoạn nuôi quả","Bón ngay trước ngày thu hoạch một hôm"],"a":"Bón trước khi cây ra hoa và trong giai đoạn nuôi quả","h":"Hãy nhớ những giai đoạn cây cần nhiều dinh dưỡng nhất.","e":"Bón thúc trước khi ra hoa giúp cây phân hoá mầm hoa tốt; bón trong giai đoạn nuôi quả giúp quả lớn đều, chất lượng cao. Ngoài ra còn bón sau thu hoạch để cây phục hồi.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cây ăn quả cần được tưới nước đầy đủ nhất vào giai đoạn nào?","o":["Giai đoạn cây ngủ nghỉ sau thu hoạch","Giai đoạn cây ra hoa, đậu quả và quả đang lớn","Giai đoạn chuẩn bị tỉa cành mùa đông","Bất kì lúc nào cây rụng lá"],"a":"Giai đoạn cây ra hoa, đậu quả và quả đang lớn","h":"Đây là lúc cây hút nhiều nước để nuôi bộ phận sinh sản.","e":"Thời kì ra hoa, đậu quả và quả lớn là lúc cây cần nhiều nước nhất; thiếu nước ở giai đoạn này dễ gây rụng hoa, rụng quả non và quả kém chất lượng.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi phun thuốc bảo vệ thực vật cho cây ăn quả sắp thu hoạch, điều quan trọng nhất phải tuân thủ là gì?","o":["Phun thuốc vào giữa trưa nắng gắt","Phun liều cao hơn hướng dẫn để trừ sâu triệt để","Phun thuốc ngay trước khi hái quả một ngày","Đảm bảo đúng thời gian cách li của thuốc trước khi thu hoạch"],"a":"Đảm bảo đúng thời gian cách li của thuốc trước khi thu hoạch","h":"Thuốc cần có đủ thời gian phân huỷ hết dư lượng trên quả.","e":"Mỗi loại thuốc bảo vệ thực vật đều có thời gian cách li quy định; phải ngừng phun trước khi thu hoạch đủ số ngày đó để dư lượng thuốc phân huỷ, đảm bảo an toàn cho người ăn.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Phương pháp chế biến món ăn nào sau đây có sử dụng nhiệt?","o":["Muối chua dưa cải","Hấp bánh cuốn","Trộn gỏi (nộm) rau củ","Ướp muối cá để bảo quản"],"a":"Hấp bánh cuốn","h":"Hãy tìm phương pháp làm chín thực phẩm bằng hơi nóng.","e":"Hấp là phương pháp chế biến có sử dụng nhiệt (nhiệt của hơi nước làm chín thực phẩm). Muối chua, trộn gỏi, ướp muối là các phương pháp không dùng nhiệt.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Bảo quản thực phẩm trong tủ lạnh giúp thực phẩm lâu hỏng chủ yếu vì lí do nào?","o":["Nhiệt độ thấp làm chậm sự phát triển của vi sinh vật gây hỏng thực phẩm","Tủ lạnh tiêu diệt hoàn toàn mọi vi khuẩn trong thực phẩm","Không khí trong tủ lạnh làm thực phẩm khô hoàn toàn","Ánh sáng trong tủ lạnh diệt được nấm mốc"],"a":"Nhiệt độ thấp làm chậm sự phát triển của vi sinh vật gây hỏng thực phẩm","h":"Vi sinh vật phát triển mạnh ở nhiệt độ ấm, chậm lại khi lạnh.","e":"Ở nhiệt độ thấp, hoạt động của vi sinh vật và các enzim gây ôi thiu bị ức chế mạnh nên thực phẩm giữ được lâu hơn, tuy nhiên bảo quản lạnh không tiêu diệt hoàn toàn vi sinh vật.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi bảo quản đông lạnh thực phẩm trong ngăn đá tủ lạnh, nhiệt độ cần đạt mức nào?","o":["Khoảng 10°C","Khoảng 5°C","Dưới 0°C, thường khoảng -18°C","Khoảng 0°C là đủ"],"a":"Dưới 0°C, thường khoảng -18°C","h":"Nước trong thực phẩm phải đóng băng hoàn toàn mới bảo quản được lâu dài.","e":"Bảo quản đông lạnh yêu cầu nhiệt độ dưới 0°C (thường khoảng -18°C) để nước trong thực phẩm đóng băng, vi sinh vật ngừng phát triển, giúp giữ thực phẩm trong thời gian dài.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Để đảm bảo an toàn vệ sinh thực phẩm, trước khi chế biến thức ăn người nấu cần làm gì?","o":["Nếm thử thực phẩm sống để kiểm tra vị","Đeo găng tay vải mỏng là đủ, không cần rửa tay","Dùng chung thớt cho thịt sống và rau ăn sống","Rửa tay sạch bằng xà phòng, giữ dụng cụ và nơi chế biến sạch sẽ"],"a":"Rửa tay sạch bằng xà phòng, giữ dụng cụ và nơi chế biến sạch sẽ","h":"Đây là yêu cầu vệ sinh cá nhân cơ bản nhất trong chế biến thực phẩm.","e":"Rửa tay bằng xà phòng trước khi chế biến và giữ vệ sinh dụng cụ, bề mặt tiếp xúc giúp hạn chế vi khuẩn từ tay và môi trường nhiễm vào thức ăn.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hành động nào sau đây đúng với nguyên tắc an toàn vệ sinh thực phẩm?","o":["Ăn thử thực phẩm đã có mùi ôi để kiểm tra","Không sử dụng thực phẩm đã ôi thiu, mốc hoặc hết hạn sử dụng","Để thức ăn đã nấu chín ngoài trời qua đêm rồi ăn tiếp","Dùng lại dầu ăn đã chiên nhiều lần cho đến khi hết"],"a":"Không sử dụng thực phẩm đã ôi thiu, mốc hoặc hết hạn sử dụng","h":"Thực phẩm hỏng chứa độc tố của vi sinh vật, đun nóng lại cũng không an toàn.","e":"Thực phẩm ôi thiu, mốc, hết hạn chứa vi sinh vật và độc tố gây bệnh; dù nấu lại cũng không loại bỏ hết độc tố nên tuyệt đối không sử dụng.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Thịt, cá tươi sống mua về chưa chế biến ngay thì nên bảo quản như thế nào?","o":["Để ở nhiệt độ phòng cho ráo nước","Bọc trong giấy báo để trên bàn bếp","Cho vào hộp kín, bảo quản ở ngăn mát hoặc ngăn đá tủ lạnh","Ngâm trong nước lã đến khi cần dùng"],"a":"Cho vào hộp kín, bảo quản ở ngăn mát hoặc ngăn đá tủ lạnh","h":"Thực phẩm tươi sống rất dễ nhiễm khuẩn ở nhiệt độ phòng.","e":"Thịt, cá tươi cần được đựng trong hộp kín và cất vào tủ lạnh (ngăn mát nếu dùng sớm, ngăn đá nếu để lâu) để hạn chế vi sinh vật phát triển và tránh lây nhiễm chéo sang thực phẩm khác.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhóm nghề nào sau đây thuộc lĩnh vực kĩ thuật, công nghệ?","o":["Kĩ sư điện, kĩ sư cơ khí, kĩ thuật viên vận hành máy","Bác sĩ, y tá, dược sĩ","Giáo viên, nhà báo, luật sư","Kế toán, nhân viên ngân hàng, thủ quỹ"],"a":"Kĩ sư điện, kĩ sư cơ khí, kĩ thuật viên vận hành máy","h":"Hãy chọn nhóm nghề gắn với máy móc, thiết bị và quy trình kĩ thuật.","e":"Lĩnh vực kĩ thuật, công nghệ gồm các nghề như kĩ sư cơ khí, kĩ sư điện - điện tử, kĩ thuật viên sửa chữa, vận hành thiết bị, lập trình viên... liên quan trực tiếp đến máy móc và công nghệ.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Phẩm chất nào đặc biệt quan trọng đối với người lao động trong lĩnh vực kĩ thuật, công nghệ?","o":["Thích làm việc tuỳ hứng, không theo quy trình","Chỉ cần sức khoẻ tốt, không cần tính cẩn thận","Hay thay đổi công việc để tránh nhàm chán","Cẩn thận, chính xác và tuân thủ nghiêm quy định an toàn lao động"],"a":"Cẩn thận, chính xác và tuân thủ nghiêm quy định an toàn lao động","h":"Công việc kĩ thuật gắn với máy móc và điện, sai sót nhỏ có thể gây hậu quả lớn.","e":"Người làm nghề kĩ thuật, công nghệ phải cẩn thận, tỉ mỉ, chính xác và tuân thủ quy trình, nhất là quy định an toàn lao động, vì công việc liên quan đến máy móc, thiết bị và nguồn năng lượng nguy hiểm.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Năng lực nào sau đây là yêu cầu cơ bản của người làm việc trong lĩnh vực kĩ thuật, công nghệ?","o":["Khả năng ghi nhớ nhiều bài thơ, văn mẫu","Khả năng đọc hiểu bản vẽ kĩ thuật và vận hành, sử dụng thiết bị, máy móc","Khả năng thuyết trình trước đám đông về lịch sử","Khả năng vẽ tranh nghệ thuật đẹp"],"a":"Khả năng đọc hiểu bản vẽ kĩ thuật và vận hành, sử dụng thiết bị, máy móc","h":"Bản vẽ kĩ thuật là 'ngôn ngữ' chung của người làm kĩ thuật.","e":"Người lao động kĩ thuật cần có tư duy kĩ thuật, đọc hiểu được bản vẽ, sơ đồ và biết vận hành, bảo dưỡng máy móc, thiết bị đúng quy trình.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi thu hoạch quả, cần chú ý điều gì để đảm bảo chất lượng sản phẩm?","o":["Thu hoạch càng sớm càng tốt, quả còn xanh cũng hái","Dùng sào rung mạnh cho quả rơi xuống đất","Thu hoạch đúng độ chín, hái nhẹ nhàng, tránh làm dập nát quả","Hái quả vào giữa trưa nắng gắt để quả nhanh khô"],"a":"Thu hoạch đúng độ chín, hái nhẹ nhàng, tránh làm dập nát quả","h":"Quả bị dập sẽ nhanh thối hỏng và giảm giá trị thương phẩm.","e":"Thu hoạch đúng độ chín giúp quả đạt chất lượng và hương vị tốt nhất; thao tác nhẹ nhàng, tránh dập nát giúp quả bảo quản được lâu và bán được giá cao.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Công việc vẽ bản vẽ kĩ thuật, tính toán và đưa ra phương án thiết kế sản phẩm thuộc nhóm nghề nào trong lĩnh vực kĩ thuật, công nghệ?","o":["Nhóm nghề bảo dưỡng, sửa chữa","Nhóm nghề thiết kế kĩ thuật","Nhóm nghề lắp ráp sản phẩm","Nhóm nghề vận hành máy móc, thiết bị"],"a":"Nhóm nghề thiết kế kĩ thuật","h":"Nghĩ đến công việc dùng bản vẽ và tính toán trước khi sản xuất.","e":"Lĩnh vực kĩ thuật, công nghệ gồm các nhóm nghề chính như thiết kế, sản xuất – chế tạo, lắp đặt – vận hành và bảo dưỡng – sửa chữa; vẽ bản vẽ và tính toán phương án thuộc nhóm nghề thiết kế kĩ thuật.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hệ thống giáo dục quốc dân của Việt Nam gồm những thành phần nào sau đây?","o":["Chỉ có giáo dục mầm non và giáo dục phổ thông","Giáo dục mầm non, giáo dục phổ thông, giáo dục nghề nghiệp và giáo dục đại học","Giáo dục phổ thông và các lớp bồi dưỡng ngắn hạn","Giáo dục nghề nghiệp và đào tạo tại doanh nghiệp"],"a":"Giáo dục mầm non, giáo dục phổ thông, giáo dục nghề nghiệp và giáo dục đại học","h":"Hệ thống giáo dục quốc dân được tổ chức thành các cấp học và trình độ đào tạo liên thông với nhau.","e":"Theo cơ cấu hệ thống giáo dục quốc dân, hệ thống gồm giáo dục mầm non, giáo dục phổ thông, giáo dục nghề nghiệp và giáo dục đại học, liên thông từ thấp đến cao.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Học sinh tốt nghiệp trung học cơ sở muốn học nghề sớm để có việc làm có thể lựa chọn con đường nào sau đây?","o":["Chỉ có thể tự học nghề tại gia đình","Đi làm ngay mà không cần qua đào tạo nghề","Học trung cấp tại trường trung cấp hoặc cơ sở giáo dục nghề nghiệp","Phải học xong trung học phổ thông mới được học nghề"],"a":"Học trung cấp tại trường trung cấp hoặc cơ sở giáo dục nghề nghiệp","h":"Sau trung học cơ sở có nhiều hướng đi, trong đó có hướng phân luồng vào giáo dục nghề nghiệp.","e":"Sau khi tốt nghiệp THCS, học sinh có thể tiếp tục học THPT hoặc theo học trình độ trung cấp tại các trường trung cấp, cơ sở giáo dục nghề nghiệp để sớm có nghề và việc làm.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đặc điểm nổi bật của thị trường lao động kĩ thuật – công nghệ ở Việt Nam hiện nay là gì?","o":["Nhu cầu lao động kĩ thuật đang giảm mạnh ở mọi ngành","Nhu cầu lao động kĩ thuật có trình độ, tay nghề cao ngày càng tăng","Lao động kĩ thuật chất lượng cao đang thừa so với nhu cầu","Doanh nghiệp chỉ tuyển lao động phổ thông, không cần tay nghề"],"a":"Nhu cầu lao động kĩ thuật có trình độ, tay nghề cao ngày càng tăng","h":"Nghĩ đến xu hướng các khu công nghiệp, nhà máy hiện đại đang cần nhân lực như thế nào.","e":"Cùng với công nghiệp hoá, hiện đại hoá, thị trường lao động Việt Nam ngày càng cần nhiều lao động kĩ thuật có trình độ và tay nghề cao, trong khi nguồn nhân lực này còn thiếu.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhóm nghề nào sau đây được dự báo phát triển mạnh nhờ xu hướng tự động hoá và chuyển đổi sang năng lượng tái tạo?","o":["Thợ khai thác than thủ công","Nhân viên đánh máy, sao chép tài liệu","Thợ vận hành máy cơ khí đơn giản không dùng điện","Kĩ thuật viên robot, tự động hoá và năng lượng tái tạo (điện mặt trời, điện gió)"],"a":"Kĩ thuật viên robot, tự động hoá và năng lượng tái tạo (điện mặt trời, điện gió)","h":"Chú ý đến các xu hướng công nghệ mới đang thay đổi cơ cấu nghề nghiệp.","e":"Tự động hoá và năng lượng tái tạo là hai xu hướng lớn, làm tăng mạnh nhu cầu kĩ thuật viên robot, tự động hoá, điện mặt trời và điện gió; nhiều nghề thủ công, đơn giản dần thu hẹp.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Bước đầu tiên trong quy trình lựa chọn nghề nghiệp là gì?","o":["Nộp hồ sơ xin việc vào một doanh nghiệp","Đăng kí học ngay một trường nghề bất kì","Hỏi ý kiến bạn bè rồi chọn theo số đông","Tìm hiểu bản thân: sở thích, năng lực, tính cách và điều kiện gia đình"],"a":"Tìm hiểu bản thân: sở thích, năng lực, tính cách và điều kiện gia đình","h":"Muốn chọn đúng nghề phải bắt đầu từ việc hiểu rõ chính mình.","e":"Quy trình lựa chọn nghề nghiệp bắt đầu bằng việc tìm hiểu bản thân, sau đó tìm hiểu thông tin nghề, đối chiếu bản thân với yêu cầu của nghề và cuối cùng ra quyết định chọn nghề.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ngoài sở thích cá nhân, khi lựa chọn nghề nghiệp học sinh cần cân nhắc thêm yếu tố nào sau đây?","o":["Nghề nào ít phải học tập, rèn luyện nhất","Nhu cầu lao động của xã hội và sự phù hợp giữa yêu cầu của nghề với năng lực, phẩm chất của bản thân","Nghề nào có tên gọi nghe hấp dẫn nhất","Nghề nào có nhiều bạn bè cùng chọn nhất"],"a":"Nhu cầu lao động của xã hội và sự phù hợp giữa yêu cầu của nghề với năng lực, phẩm chất của bản thân","h":"Một nghề phù hợp phải vừa hợp với mình, vừa có nhu cầu thật ngoài xã hội.","e":"Chọn nghề đúng cần kết hợp ba cơ sở: hiểu bản thân, hiểu nghề (yêu cầu về năng lực, phẩm chất) và hiểu nhu cầu thị trường lao động, tránh chọn nghề theo phong trào.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong dự án tự đánh giá phục vụ định hướng nghề nghiệp, học sinh cần tự đánh giá những khía cạnh nào của bản thân?","o":["Đánh giá mức thu nhập mong muốn trong tương lai","Chỉ cần đánh giá điểm số các môn học ở trường","Chỉ cần đánh giá sở thích, không cần quan tâm sức khoẻ","Sở thích, năng lực, phẩm chất và điều kiện sức khoẻ so với yêu cầu của nghề dự định chọn"],"a":"Sở thích, năng lực, phẩm chất và điều kiện sức khoẻ so với yêu cầu của nghề dự định chọn","h":"Tự đánh giá phải toàn diện và luôn đặt cạnh yêu cầu cụ thể của nghề.","e":"Dự án tự đánh giá yêu cầu học sinh nhìn nhận sở thích, năng lực học tập và làm việc, phẩm chất, sức khoẻ của mình rồi đối chiếu với yêu cầu của nghề để biết mình phù hợp đến đâu.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Chất đạm (protein) có vai trò quan trọng nhất nào đối với cơ thể người?","o":["Chỉ cung cấp nhiệt lượng để giữ ấm cơ thể","Giúp cơ thể dự trữ nước","Tạo vị ngọt cho các món ăn","Xây dựng và tái tạo tế bào, giúp cơ thể sinh trưởng và phát triển"],"a":"Xây dựng và tái tạo tế bào, giúp cơ thể sinh trưởng và phát triển","h":"Protein là thành phần cấu tạo nên cơ bắp, tế bào của cơ thể.","e":"Chất đạm là vật liệu xây dựng của cơ thể: tạo nên tế bào, cơ, enzym..., đặc biệt quan trọng với trẻ em đang lớn; chất đường bột và chất béo chủ yếu cung cấp năng lượng.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Chất béo (lipid) có điểm nổi bật nào sau đây so với các chất dinh dưỡng khác?","o":["Chỉ có trong thực phẩm có nguồn gốc thực vật","Không cung cấp năng lượng cho cơ thể","Cung cấp nhiều năng lượng nhất trong các chất dinh dưỡng","Là chất duy nhất cấu tạo nên tế bào cơ thể"],"a":"Cung cấp nhiều năng lượng nhất trong các chất dinh dưỡng","h":"So sánh lượng năng lượng của 1 gam chất béo với 1 gam chất đường bột.","e":"1 gam chất béo cung cấp khoảng 9 kcal, cao hơn hẳn chất đường bột và chất đạm (khoảng 4 kcal/gam), nên chất béo là nguồn dự trữ năng lượng đậm đặc nhất của cơ thể.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây cho thấy thịt tươi đã bị ôi thiu, không nên sử dụng?","o":["Thịt đàn hồi tốt, ấn vào không để lại vết lõm","Thịt không mùi, thớ thịt săn chắc","Thịt có màu đỏ tươi, mặt cắt khô ráo","Thịt có mùi hôi, bề mặt nhớt và đổi màu sẫm"],"a":"Thịt có mùi hôi, bề mặt nhớt và đổi màu sẫm","h":"Dựa vào các giác quan: nhìn màu sắc, ngửi mùi, sờ bề mặt của thịt.","e":"Thực phẩm ôi thiu thường đổi màu, có mùi hôi khó chịu và bề mặt nhớt do vi sinh vật phát triển; thịt tươi thì đỏ tươi, không mùi lạ, đàn hồi tốt. Tuyệt đối không dùng thực phẩm đã ôi thiu.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Biện pháp nào sau đây giúp phòng tránh ngộ độc thực phẩm hiệu quả nhất trong gia đình?","o":["Nếm thử thực phẩm nghi ngờ hỏng để kiểm tra trước khi ăn","Dùng chung thớt cho thực phẩm sống và chín để tiết kiệm","Ăn chín, uống sôi; không sử dụng thực phẩm ôi thiu, hết hạn sử dụng","Để thức ăn chín qua đêm ở nhiệt độ phòng rồi ăn lại"],"a":"Ăn chín, uống sôi; không sử dụng thực phẩm ôi thiu, hết hạn sử dụng","h":"Ngộ độc thực phẩm chủ yếu do vi khuẩn trong thức ăn sống, ôi thiu gây ra.","e":"Nấu chín kĩ và đun sôi tiêu diệt phần lớn vi khuẩn gây bệnh; thực phẩm ôi thiu, hết hạn có thể chứa độc tố nên phải loại bỏ. Thức ăn chín cần bảo quản đúng cách và dùng thớt riêng cho đồ sống, đồ chín.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Một thực đơn bữa ăn gồm: gạo 30 000 đồng, thịt lợn 60 000 đồng, rau xanh 15 000 đồng. Chi phí thực phẩm của bữa ăn này là bao nhiêu?","o":["120 000 đồng","90 000 đồng","100 000 đồng","105 000 đồng"],"a":"105 000 đồng","h":"Chi phí bữa ăn bằng tổng số tiền mua tất cả thực phẩm theo thực đơn.","e":"Chi phí thực phẩm của bữa ăn = 30 000 + 60 000 + 15 000 = 105 000 đồng. Đây là bước cơ bản khi lập dự toán chi phí cho bữa ăn theo thực đơn.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Phương pháp rán khác phương pháp luộc ở điểm nào?","o":["Rán làm chín thực phẩm trong chất béo ở nhiệt độ cao, luộc làm chín thực phẩm trong nước","Rán làm chín bằng hơi nước, luộc làm chín bằng dầu nóng","Rán chỉ dùng cho rau, luộc chỉ dùng cho thịt","Rán không cần dùng nhiệt, luộc cần dùng nhiệt"],"a":"Rán làm chín thực phẩm trong chất béo ở nhiệt độ cao, luộc làm chín thực phẩm trong nước","h":"Chú ý đến môi trường truyền nhiệt của từng phương pháp.","e":"Luộc và rán đều là phương pháp chế biến có sử dụng nhiệt, nhưng luộc dùng nước làm môi trường truyền nhiệt, còn rán dùng chất béo (dầu, mỡ) nóng; hấp dùng hơi nước.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi muối chua rau quả, yếu tố nào giúp rau quả chua dần và bảo quản được lâu hơn?","o":["Vi khuẩn lactic lên men tạo ra axit lactic trong môi trường nước muối","Ánh nắng mặt trời chiếu trực tiếp vào vại muối","Không khí trong vại giúp rau quả lên men","Đường trong rau quả tự biến thành giấm ngay khi ngâm nước lã"],"a":"Vi khuẩn lactic lên men tạo ra axit lactic trong môi trường nước muối","h":"Muối chua là ứng dụng của quá trình lên men.","e":"Muối chua dựa vào vi khuẩn lactic lên men đường trong rau quả thành axit lactic; môi trường axit ức chế vi sinh vật gây thối nên rau quả chua ngon và giữ được lâu hơn.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Vì sao các món trộn, gỏi (chế biến không sử dụng nhiệt) đòi hỏi vệ sinh nguyên liệu nghiêm ngặt hơn các món nấu chín?","o":["Vì các món này thường để được rất lâu sau khi chế biến","Vì nguyên liệu của món trộn, gỏi luôn đắt tiền hơn","Vì thực phẩm không được làm chín bằng nhiệt nên vi khuẩn gây bệnh trên nguyên liệu không bị tiêu diệt","Vì các món này có nhiều gia vị nên dễ bị nhiễm khuẩn hơn"],"a":"Vì thực phẩm không được làm chín bằng nhiệt nên vi khuẩn gây bệnh trên nguyên liệu không bị tiêu diệt","h":"Nghĩ đến vai trò diệt khuẩn của nhiệt khi nấu chín thực phẩm.","e":"Nhiệt độ cao khi nấu chín tiêu diệt hầu hết vi khuẩn gây bệnh; món không qua nhiệt không có bước bảo vệ này nên nguyên liệu phải thật tươi, rửa sạch, sơ chế vệ sinh và ăn ngay sau khi chế biến.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đồng hồ vạn năng (đồng hồ đo đa năng) được dùng để đo những đại lượng điện nào?","o":["Đo được điện năng tiêu thụ trong một tháng","Chỉ đo được công suất tiêu thụ của thiết bị","Điện áp, cường độ dòng điện và điện trở","Chỉ đo được cường độ dòng điện"],"a":"Điện áp, cường độ dòng điện và điện trở","h":"Tên gọi “đa năng / vạn năng” gợi ý dụng cụ này đo được nhiều đại lượng.","e":"Đồng hồ vạn năng là dụng cụ đo điện cơ bản có thể đo điện áp, cường độ dòng điện, điện trở và kiểm tra thông mạch; điện năng tiêu thụ được đo bằng công tơ điện.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ưu điểm của ampe kìm khi đo cường độ dòng điện trong mạch là gì?","o":["Cho kết quả chính xác hơn mọi dụng cụ đo khác trong mọi trường hợp","Đo được dòng điện mà không cần ngắt mạch hay cắt dây dẫn","Không cần nguồn điện vẫn đo được mọi đại lượng","Đo được cả điện áp và điện trở cùng lúc"],"a":"Đo được dòng điện mà không cần ngắt mạch hay cắt dây dẫn","h":"Chú ý đến cấu tạo hàm kìm kẹp quanh dây dẫn của ampe kìm.","e":"Ampe kìm có hàm kẹp ôm quanh dây dẫn để cảm ứng dòng điện, nên đo được cường độ dòng điện ngay khi mạch đang làm việc mà không phải ngắt mạch hay cắt dây, rất tiện và an toàn.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Thiết kế mạng điện trong nhà cần đáp ứng những yêu cầu nào sau đây?","o":["Dùng càng nhiều thiết bị càng tốt, không cần tính tải","Đảm bảo an toàn, thuận tiện khi sử dụng, kinh tế và có tính thẩm mĩ","Chỉ cần rẻ nhất, không cần quan tâm an toàn","Chỉ cần đẹp, dây dẫn có thể đi nổi tùy ý"],"a":"Đảm bảo an toàn, thuận tiện khi sử dụng, kinh tế và có tính thẩm mĩ","h":"Một mạng điện tốt phải cân bằng đồng thời nhiều mặt, trong đó an toàn là hàng đầu.","e":"Thiết kế mạng điện trong nhà phải đồng thời đảm bảo an toàn điện, thuận tiện sử dụng và bảo trì, tiết kiệm chi phí (kinh tế) và hài hoà với không gian nhà ở (thẩm mĩ).","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Sơ đồ nguyên lí của mạng điện khác sơ đồ lắp đặt ở điểm nào?","o":["Sơ đồ nguyên lí dùng để tính tiền vật liệu, sơ đồ lắp đặt thì không","Sơ đồ nguyên lí thể hiện đúng vị trí từng ổ cắm trong phòng","Hai sơ đồ hoàn toàn giống nhau, chỉ khác tên gọi","Sơ đồ nguyên lí chỉ thể hiện nguyên lí hoạt động và mối liên hệ điện giữa các phần tử, không thể hiện vị trí lắp đặt thực tế"],"a":"Sơ đồ nguyên lí chỉ thể hiện nguyên lí hoạt động và mối liên hệ điện giữa các phần tử, không thể hiện vị trí lắp đặt thực tế","h":"Nhớ lại: sơ đồ lắp đặt mới thể hiện vị trí, cách bố trí các phần tử trong nhà.","e":"Sơ đồ nguyên lí trình bày cách nối điện và nguyên lí làm việc của mạch bằng kí hiệu, không quan tâm vị trí thật; sơ đồ lắp đặt thể hiện vị trí, cách lắp đặt cụ thể của từng phần tử để thi công.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi chọn áptômát cho một nhánh mạch điện trong nhà, căn cứ quan trọng nhất là gì?","o":["Dòng điện định mức của áptômát phải phù hợp với công suất (tải) của các thiết bị trên nhánh đó","Chọn áptômát có dòng định mức càng lớn càng tốt cho mọi nhánh","Mọi nhánh trong nhà đều dùng chung một loại áptômát 63 A","Chọn theo màu sắc vỏ cho hợp với bảng điện"],"a":"Dòng điện định mức của áptômát phải phù hợp với công suất (tải) của các thiết bị trên nhánh đó","h":"Áptômát bảo vệ theo dòng điện: quá nhỏ thì hay nhảy, quá lớn thì không bảo vệ được dây dẫn.","e":"Áptômát được chọn theo dòng điện làm việc của nhánh mạch: dòng định mức phải lớn hơn dòng tải tính toán một mức hợp lí nhưng không quá lớn, để vừa không nhảy oan, vừa cắt kịp thời khi quá tải, ngắn mạch.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Tổng chi phí lắp đặt mạng điện trong nhà gồm những khoản chính nào?","o":["Gồm tiền mua vật liệu và tiền điện sử dụng trong một năm","Chỉ gồm tiền mua thiết bị điện","Chi phí vật liệu, chi phí thiết bị và chi phí nhân công lắp đặt","Chỉ gồm tiền mua dây dẫn điện"],"a":"Chi phí vật liệu, chi phí thiết bị và chi phí nhân công lắp đặt","h":"Lập dự toán phải tính đủ cả phần “cứng” mua sắm và phần công thi công.","e":"Dự toán lắp đặt mạng điện gồm ba khoản chính: vật liệu (dây dẫn, ống luồn...), thiết bị (áptômát, ổ cắm, công tắc...) và nhân công lắp đặt; cộng đủ ba khoản mới ra tổng chi phí.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi lập bảng dự trù kinh phí lắp đặt mạng điện trong nhà, mỗi hạng mục vật liệu, thiết bị cần ghi rõ những thông tin nào?","o":["Ghi tên vật liệu và địa chỉ nơi sản xuất","Chỉ cần ghi tổng số tiền của toàn bộ công trình","Tên vật liệu, thiết bị; số lượng; đơn giá và thành tiền","Chỉ cần ghi tên vật liệu, không cần số lượng và giá"],"a":"Tên vật liệu, thiết bị; số lượng; đơn giá và thành tiền","h":"Bảng dự trù phải tính được thành tiền cho từng hạng mục rồi mới cộng tổng.","e":"Bảng dự trù kinh phí được lập theo từng hạng mục với các cột: tên vật liệu – thiết bị, đơn vị, số lượng, đơn giá, thành tiền (số lượng × đơn giá); cộng các thành tiền và chi phí nhân công sẽ được tổng dự toán.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Sau khi lắp đặt xong mạch điện trên bảng điện, trước khi đưa vào sử dụng cần thực hiện công việc nào?","o":["Tháo các thiết bị bảo vệ ra để mạch thông thoáng","Đóng điện ngay cho tất cả các thiết bị cùng lúc","Sơn lại bảng điện cho đẹp rồi mới kiểm tra sau","Kiểm tra lại các mối nối, độ cách điện và vận hành thử toàn bộ mạch"],"a":"Kiểm tra lại các mối nối, độ cách điện và vận hành thử toàn bộ mạch","h":"Bước cuối của quy trình lắp đặt luôn là kiểm tra và nghiệm thu an toàn.","e":"Quy trình lắp đặt kết thúc bằng việc kiểm tra mối nối, cách điện, đối chiếu với sơ đồ rồi vận hành thử từng phần; chỉ khi mạch hoạt động đúng và an toàn mới đóng điện sử dụng chính thức.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ưu điểm nổi bật của nhân giống vô tính (chiết cành, ghép) đối với cây ăn quả là gì?","o":["Cây con giữ được đặc tính tốt của cây mẹ và sớm cho quả","Cây con có thể mang đặc tính của nhiều giống khác nhau tùy ý","Không cần chọn cây mẹ, cành nào chiết cũng cho quả ngon","Cây con luôn có bộ rễ khỏe hơn hẳn cây trồng từ hạt"],"a":"Cây con giữ được đặc tính tốt của cây mẹ và sớm cho quả","h":"So sánh với trồng bằng hạt: cây hạt lâu cho quả và dễ bị phân li tính trạng.","e":"Chiết, ghép là nhân giống vô tính nên cây con mang đúng đặc tính di truyền của cây mẹ (quả ngon, sai quả) và ra hoa, kết quả sớm hơn nhiều so với cây gieo từ hạt.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cây ăn quả có múi (cam, quýt, bưởi) sinh trưởng tốt nhất trong điều kiện đất nào sau đây?","o":["Đất tơi xốp, giàu mùn, thoát nước tốt, độ pH khoảng 5,5 – 6,5","Đất sét nặng, bí chặt, pH rất cao","Đất cát khô cằn, nghèo dinh dưỡng","Đất trũng, thường xuyên ngập nước"],"a":"Đất tơi xốp, giàu mùn, thoát nước tốt, độ pH khoảng 5,5 – 6,5","h":"Cây có múi rất sợ úng rễ nhưng lại cần đất giàu dinh dưỡng và hơi chua nhẹ.","e":"Cây có múi ưa đất tơi xốp, tầng canh tác dày, giàu mùn, thoát nước tốt và hơi chua (pH 5,5 – 6,5); đất úng nước làm rễ bị thối, cây sinh trưởng kém và dễ chết.","t":"cn-lop9","g":9,"l":"thu-thach"},{"p":"Để cây nhãn phân hoá mầm hoa và ra hoa tốt, điều kiện thời tiết nào sau đây là cần thiết?","o":["Nắng nóng gay gắt trong suốt mùa đông","Mưa nhiều, ẩm ướt liên tục quanh năm","Có một thời kì khô hạn và nhiệt độ thấp (lạnh) trước vụ hoa","Thời tiết mát mẻ, mưa đều vào đúng lúc cây ra hoa"],"a":"Có một thời kì khô hạn và nhiệt độ thấp (lạnh) trước vụ hoa","h":"Nhãn là cây cần “nghỉ” khô lạnh để tích lũy và phân hoá mầm hoa.","e":"Cây nhãn cần một giai đoạn khô hạn và lạnh vào cuối năm để phân hoá mầm hoa; nếu thời kì này mưa ẩm, ấm áp thì cây ra lộc đông thay vì ra hoa, làm giảm năng suất.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cây xoài có yêu cầu ngoại cảnh đặc trưng nào sau đây?","o":["Ưa khí hậu nóng, nhiều nắng, cần có mùa khô rõ rệt để ra hoa và rất sợ sương giá","Chỉ sinh trưởng tốt ở vùng đất ngập nước quanh năm","Ưa khí hậu lạnh, cần mùa đông dài có tuyết","Cần che bóng râm mát trong suốt thời gian sinh trưởng"],"a":"Ưa khí hậu nóng, nhiều nắng, cần có mùa khô rõ rệt để ra hoa và rất sợ sương giá","h":"Xoài là cây ăn quả nhiệt đới điển hình của vùng nóng.","e":"Xoài sinh trưởng tốt ở khí hậu nóng, nhiều nắng; cây cần mùa khô rõ rệt để phân hoá mầm hoa và ra hoa, đồng thời rất mẫn cảm với lạnh và sương giá nên không trồng được ở vùng rét đậm.","t":"cn-lop9","g":9,"l":"nhe-nhang"},{"p":"Yêu cầu ngoại cảnh đặc trưng của cây sầu riêng là gì?","o":["Ưa khí hậu khô hạn, ít mưa, chịu lạnh tốt","Chỉ trồng được ở vùng núi cao lạnh quanh năm","Cần đất trũng, giữ nước thường xuyên quanh gốc","Ưa khí hậu nóng ẩm, mưa nhiều, sợ lạnh và gió mạnh, cần đất sâu và thoát nước tốt"],"a":"Ưa khí hậu nóng ẩm, mưa nhiều, sợ lạnh và gió mạnh, cần đất sâu và thoát nước tốt","h":"Sầu riêng là cây nhiệt đới điển hình của miền Nam.","e":"Sầu riêng cần khí hậu nóng ẩm, lượng mưa lớn và phân bố đều, nhiệt độ ổn định; cây sợ lạnh, sợ gió mạnh làm gãy cành, rụng quả và cần đất sâu, tơi xốp, thoát nước tốt, không ngập úng.","t":"cn-lop9","g":9,"l":"nhe-nhang"}];